      const msgToSave = { 
          ...message, 
          files: cleanFilesForDB(message.files)
      };
      await setDoc(doc(db, "messages", message.id), sanitizeData(msgToSave));
      logSystemAction('CREATE', 'Message', `پیام جدید از ${message.senderName} ارسال شد`, message.senderName, message.id);
  } catch(e) {
      throw e;
  }
};

