interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
  config: any;
}

export const ReportManager: React.FC<Props> = ({ currentUser, personnel, lang, config }) => {
  const [activeTab, setActiveTab] = useState<ReportType>('daily');
  const [reports, setReports] = useState<PerformanceReport[]>([]);
  const [filterUserId, setFilterUserId] = useState<string>(currentUser.id);
  const [showAddModal, setShowAddModal] = useState(false);

  // Form State
  const [editingReportId, setEditingReportId] = useState<string | null>(null);
  const [newContent, setNewContent] = useState('');
  const [tempTasks, setTempTasks] = useState<string[]>([]);
  const [currentTask, setCurrentTask] = useState('');
  const [reportDate, setReportDate] = useState(new Date().toISOString().split('T')[0]);

  const isMaster = currentUser.username === 'master';

  useEffect(() => {
    const unsub = subscribeToReports(setReports);
    return () => unsub();
  }, []);

  const t = {
    fa: {
      header: 'سامانه گزارش‌دهی عملکرد',
      sub: 'ثبت فعالیت‌ها به صورت خطی و تجمیع هوشمند',
      tabs: { daily: 'گزارش روزانه', weekly: 'گزارش هفتگی', monthly: 'گزارش ماهانه' },
      new: 'ثبت گزارش عملکرد',
      edit: 'ویرایش گزارش',
      filterUser: 'مشاهده گزارش‌های:',
      tasks: 'لیست فعالیت‌های انجام شده (گزارش خطی)',
      addTask: 'افزودن سطر',
      content: 'توضیحات و موانع اجرایی',
      save: 'تایید و ثبت نهایی',
      update: 'بروزرسانی تغییرات',
      cancel: 'انصراف',
      empty: 'هنوز گزارشی برای این کاربر ثبت نشده است.',
      topPerformer: 'انتخاب به عنوان کارمند نمونه',
      isTop: 'کارمند نمونه منتخب',
      currentTop: 'کارمند نمونه فعلی',
      removeTop: 'حذف انتخاب',
      itemPlaceholder: 'مثلاً: پیگیری تیکت شماره ۱۲۴ یا جلسه با مشتری...',
      date: 'تاریخ گزارش'
    },
    en: {
      header: 'Performance Reporting',
      sub: 'Linear activity logging and smart aggregation',
      tabs: { daily: 'Daily', weekly: 'Weekly', monthly: 'Monthly' },
      new: 'Add Performance Report',
      edit: 'Edit Report',
      filterUser: 'View reports for:',
      tasks: 'Activity List (Linear Report)',
      addTask: 'Add Line',
      content: 'Notes & Blockers',
      save: 'Submit Report',
      update: 'Update Report',
      cancel: 'Cancel',
      empty: 'No reports found for this user.',
      topPerformer: 'Set as Top Performer',
      isTop: 'Selected Top Performer',
      currentTop: 'Top Performer',
      removeTop: 'Clear Selection',
      itemPlaceholder: 'e.g., Followed up on Ticket #124...',
      date: 'Report Date'
    }
  }[lang];

  const filteredReports = useMemo(() => {
    return reports.filter(r => r.userId === filterUserId && r.type === activeTab);
  }, [reports, filterUserId, activeTab]);

  const handleAddTask = () => {
    if (!currentTask.trim()) return;
    setTempTasks([...tempTasks, currentTask.trim()]);
    setCurrentTask('');
  };

  const handleOpenEdit = (report: PerformanceReport) => {
      setEditingReportId(report.id);
      setNewContent(report.content);
      setTempTasks(report.completedTasks);
      setReportDate(report.date);
      setShowAddModal(true);
  };

  const handleSaveReport = async () => {
    if (tempTasks.length === 0 && !newContent.trim()) return;

    if (editingReportId) {
        await updateReport(editingReportId, {
            content: newContent,
            completedTasks: tempTasks,
            date: reportDate,
            updatedAt: new Date().toISOString()
        }, currentUser.fullName);
    } else {
        const report: PerformanceReport = {
            id: `rep-${Date.now()}`,
            userId: currentUser.id,
            userName: currentUser.fullName,
            type: activeTab,
            date: reportDate,
            content: newContent,
            completedTasks: tempTasks,
            status: 'submitted',
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString()
        };

        await saveReport(report);

        if (activeTab === 'daily') {
            const weekKey = getWeekKey(new Date(reportDate));
            const monthKey = reportDate.slice(0, 7);
            await autoUpdateAggregatedReport(weekKey, 'weekly', report);
            await autoUpdateAggregatedReport(monthKey, 'monthly', report);
        }
    }

    handleCloseModal();
  };

  const handleCloseModal = () => {
      setShowAddModal(false);
      setEditingReportId(null);
      setTempTasks([]);
      setNewContent('');
  };

  const getWeekKey = (date: Date) => {
    const firstDayOfYear = new Date(date.getFullYear(), 0, 1);
    const pastDaysOfYear = (date.getTime() - firstDayOfYear.getTime()) / 86400000;
    return `${date.getFullYear()}-W${Math.ceil((pastDaysOfYear + firstDayOfYear.getDay() + 1) / 7)}`;
  };

  const autoUpdateAggregatedReport = async (dateKey: string, type: ReportType, sourceDaily: PerformanceReport) => {
      const existing = reports.find(r => r.userId === currentUser.id && r.type === type && r.date === dateKey);
      const summaryText = `[${sourceDaily.date}]: ${sourceDaily.completedTasks.join(' | ')}`;

      if (existing) {
          const updatedTasks = [...existing.completedTasks, ...sourceDaily.completedTasks];
          const updatedContent = existing.content + "\n" + summaryText;
          await updateReport(existing.id, { 
              completedTasks: updatedTasks, 
              content: updatedContent,
              updatedAt: new Date().toISOString() 
          }, 'System');
      } else {
          const newAggReport: PerformanceReport = {
              id: `agg-${Date.now()}-${Math.random()}`,
              userId: currentUser.id,
              userName: currentUser.fullName,
              type,
              date: dateKey,
              content: `تجمیع خودکار:\n${summaryText}`,
              completedTasks: sourceDaily.completedTasks,
              status: 'submitted',
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString()
          };
          await saveReport(newAggReport);
      }
  };

  const handleSetTopPerformer = async (userId: string) => {
    if (!isMaster) return;
    await saveAppConfigToCloud({ ...config, topPerformerId: userId });
    alert(lang === 'fa' ? 'کارمند نمونه با موفقیت تغییر یافت.' : 'Top performer updated successfully.');
  };

  const handleClearTopPerformer = async () => {
      if (!isMaster) return;
      await saveAppConfigToCloud({ ...config, topPerformerId: null });
      alert(lang === 'fa' ? 'انتخاب کارمند نمونه لغو شد.' : 'Top performer selection cleared.');
  };

  return (
    <div className="space-y-6 animate-fade-in">
        <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-2xl border border-gray-100 shadow-sm gap-4">
            <div className="flex items-center gap-4">
                <div className="bg-indigo-100 text-indigo-600 p-3 rounded-xl"><IconClipboard className="w-6 h-6" /></div>
                <div>
                    <h2 className="text-xl font-bold text-gray-800">{t.header}</h2>
                    <p className="text-sm text-gray-500">{t.sub}</p>
                </div>
            </div>
            <div className="flex gap-2">
                <div className="flex bg-gray-100 p-1 rounded-xl">
                    {(['daily', 'weekly', 'monthly'] as ReportType[]).map(tab => (
                        <button key={tab} onClick={() => setActiveTab(tab)} className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === tab ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>{t.tabs[tab]}</button>
                    ))}
                </div>
                <button onClick={() => { setEditingReportId(null); setShowAddModal(true); }} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-indigo-700 flex items-center gap-2 shadow-lg shadow-indigo-200">
                    <IconPlus className="w-5 h-5" /> {t.new}
                </button>
            </div>
        </div>

        <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="flex items-center gap-3">
                <IconSearch className="w-5 h-5 text-gray-400" />
                <label className="text-sm font-bold text-gray-700">{t.filterUser}</label>
                <select 
                    className="outline-none bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-200 text-sm"
                    value={filterUserId}
                    onChange={(e) => setFilterUserId(e.target.value)}
                >
                    {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                </select>
            </div>
            {isMaster && config.topPerformerId && (
                <div className="flex items-center gap-3 bg-amber-50 text-amber-700 px-3 py-1.5 rounded-lg border border-amber-100 text-sm font-bold">
                    <div className="flex items-center gap-2">
                        <IconAward className="w-4 h-4" />
                        {t.currentTop}: {personnel.find(p => p.id === config.topPerformerId)?.fullName}
                    </div>
                    <button onClick={handleClearTopPerformer} className="p-1 hover:bg-amber-200 rounded-full transition-colors text-amber-500 hover:text-amber-700" title={t.removeTop}>✕</button>
                </div>
            )}
        </div>

        <div className="grid grid-cols-1 gap-4">
            {filteredReports.map(report => (
                <div key={report.id} className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm hover:shadow-md transition-all group">
                    <div className="flex justify-between items-start mb-4">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-full bg-indigo-50 flex items-center justify-center text-indigo-600 font-bold">{report.userName.charAt(0)}</div>
                            <div>
                                <div className="font-bold text-gray-900">{report.userName}</div>
                                <div className="text-xs text-gray-400 font-mono">{report.date}</div>
                            </div>
                        </div>
                        <div className="flex items-center gap-2">
                            {isMaster && (
                                <>
                                    <button 
                                        onClick={() => handleSetTopPerformer(report.userId)} 
                                        className={`opacity-0 group-hover:opacity-100 px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1 transition-all ${config.topPerformerId === report.userId ? 'bg-amber-500 text-white shadow-sm' : 'bg-amber-100 text-amber-700 hover:bg-amber-200'}`}
                                    >
                                        <IconAward className="w-4 h-4" /> {config.topPerformerId === report.userId ? t.isTop : t.topPerformer}
                                    </button>
                                    <button 
                                        onClick={() => handleOpenEdit(report)}
                                        className="opacity-0 group-hover:opacity-100 bg-blue-100 text-blue-700 px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1 transition-all hover:bg-blue-200"
                                    >
                                        <IconEdit className="w-4 h-4" /> {t.edit}
                                    </button>
                                </>
                            )}
                            <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-1 rounded">{new Date(report.createdAt).toLocaleTimeString()}</span>
                        </div>
                    </div>

                    <div className="space-y-4">
                        <div>
                            <h4 className="text-xs font-bold text-gray-400 mb-2 uppercase tracking-wider flex items-center gap-1"><IconList className="w-3 h-3" /> {t.tasks}</h4>
                            <div className="space-y-2">
                                {report.completedTasks.map((task, i) => (
                                    <div key={i} className="flex items-center gap-3 text-sm text-gray-700 bg-gray-50/50 p-3 rounded-xl border border-gray-100">
                                        <div className="w-5 h-5 rounded-full bg-green-100 text-green-600 flex items-center justify-center shrink-0 font-bold text-[10px]">{i+1}</div>
                                        {task}
                                    </div>
                                ))}
                            </div>
                        </div>
                        {report.content && (
                            <div className="pt-4 border-t border-gray-50">
                                <h4 className="text-xs font-bold text-gray-400 mb-1 uppercase tracking-wider">{t.content}</h4>
                                <p className="text-sm text-gray-600 whitespace-pre-wrap leading-relaxed">{report.content}</p>
                            </div>
                        )}
                        {report.updatedAt !== report.createdAt && (
                            <div className="text-[10px] text-gray-400 mt-2 italic">
                                آخرین ویرایش: {new Date(report.updatedAt).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}
                            </div>
                        )}
                    </div>
                </div>
            ))}
            {filteredReports.length === 0 && <div className="py-12 text-center text-gray-400 bg-white rounded-2xl border-2 border-dashed">{t.empty}</div>}
        </div>

        {/* Modal (Add/Edit) */}
        {showAddModal && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
                <div className="bg-white rounded-3xl w-full max-w-xl shadow-2xl animate-fade-in overflow-hidden flex flex-col max-h-[90vh]">
                    <div className="p-6 border-b border-gray-100 bg-indigo-50 flex justify-between items-center">
                        <h3 className="font-bold text-indigo-900 text-lg flex items-center gap-2">
                           {editingReportId ? <IconEdit className="w-5 h-5" /> : <IconPlus className="w-5 h-5" />}
                           {editingReportId ? t.edit : t.new} ({t.tabs[activeTab]})
                        </h3>
                        <button onClick={handleCloseModal} className="text-gray-400 hover:text-gray-600">✕</button>
                    </div>
                    <div className="p-6 overflow-y-auto space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 mb-1">{t.date}</label>
                                <input type="date" className="w-full border rounded-xl p-2.5 outline-none focus:ring-2 focus:ring-indigo-500" value={reportDate} onChange={e => setReportDate(e.target.value)} />
                            </div>
                        </div>

                        <div className="bg-gray-50 p-4 rounded-2xl border border-gray-200">
                            <label className="block text-sm font-bold text-gray-700 mb-3 flex items-center gap-2">
                                <IconList className="w-4 h-4 text-indigo-600" />
                                {t.tasks}
                            </label>
                            <div className="space-y-2 mb-4">
                                {tempTasks.map((task, i) => (
                                    <div key={i} className="flex items-center gap-2 bg-white p-3 rounded-xl border border-gray-200 shadow-sm group">
                                        <span className="w-6 h-6 rounded-full bg-gray-100 flex items-center justify-center text-[10px] font-bold text-gray-500 shrink-0">{i+1}</span>
                                        <span className="flex-grow text-sm text-gray-700">{task}</span>
                                        <button onClick={() => setTempTasks(tempTasks.filter((_, idx) => idx !== i))} className="text-red-400 hover:text-red-600 p-1 opacity-0 group-hover:opacity-100 transition-opacity"><IconTrash className="w-4 h-4" /></button>
                                    </div>
                                ))}
                            </div>
                            <div className="flex gap-2">
                                <input 
                                    className="flex-grow border border-gray-300 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-indigo-500 bg-white" 
                                    placeholder={t.itemPlaceholder} 
                                    value={currentTask} 
                                    onChange={e => setCurrentTask(e.target.value)} 
                                    onKeyDown={e => e.key === 'Enter' && (e.preventDefault(), handleAddTask())}
                                />
                                <button onClick={handleAddTask} className="bg-indigo-600 text-white px-4 rounded-xl font-bold hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-100">{t.addTask}</button>
                            </div>
                        </div>

                        <div>
                            <label className="block text-xs font-bold text-gray-500 mb-1">{t.content}</label>
                            <textarea 
                                className="w-full border rounded-xl p-3 text-sm outline-none focus:ring-2 focus:ring-indigo-500" 
                                rows={3} 
                                value={newContent} 
                                onChange={e => setNewContent(e.target.value)}
                            />
                        </div>
                    </div>
                    <div className="p-4 bg-gray-50 border-t flex gap-3">
                        <button onClick={handleCloseModal} className="flex-1 py-3 text-gray-600 font-bold hover:bg-gray-100 rounded-xl transition-colors">{t.cancel}</button>
                        <button onClick={handleSaveReport} className="flex-1 py-3 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-200">
                            {editingReportId ? t.update : t.save}
                        </button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { PerformanceReport, Personnel, ReportType } from '../types';
import { IconClipboard, IconPlus, IconCheck, IconSearch, IconTrash, IconAward, IconList, IconEdit, IconLock } from './Icons';
import { saveReport, updateReport, subscribeToReports, saveAppConfigToCloud } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
  config: any;
}

export const ReportManager: React.FC<Props> = ({ currentUser, personnel, lang, config }) => {
  const [activeTab, setActiveTab] = useState<ReportType>('daily');
  const [reports, setReports] = useState<PerformanceReport[]>([]);
  const [filterUserId, setFilterUserId] = useState<string>(currentUser.id);
  const [showAddModal, setShowAddModal] = useState(false);

  // Form State
  const [editingReportId, setEditingReportId] = useState<string | null>(null);
  const [newContent, setNewContent] = useState('');
  const [tempTasks, setTempTasks] = useState<string[]>([]);
  const [currentTask, setCurrentTask] = useState('');
  const [reportDate, setReportDate] = useState(new Date().toISOString().split('T')[0]);

  const isMaster = currentUser.username === 'master';
  const todayStr = new Date().toISOString().split('T')[0];

  useEffect(() => {
    const unsub = subscribeToReports(setReports);
    return () => unsub();
  }, []);

  const t = {
    fa: {
      header: 'سامانه گزارش‌دهی عملکرد',
      sub: 'ثبت فعالیت‌ها به صورت خطی و تجمیع هوشمند',
      tabs: { daily: 'گزارش روزانه', weekly: 'گزارش هفتگی', monthly: 'گزارش ماهانه' },
      new: 'ثبت گزارش عملکرد',
      edit: 'ویرایش گزارش',
      filterUser: 'مشاهده گزارش‌های:',
      tasks: 'لیست فعالیت‌های انجام شده (گزارش خطی)',
      addTask: 'افزودن سطر',
      content: 'توضیحات و موانع اجرایی',
      save: 'تایید و ثبت نهایی',
      update: 'بروزرسانی تغییرات',
      cancel: 'انصراف',
      empty: 'هنوز گزارشی برای این کاربر ثبت نشده است.',
      topPerformer: 'انتخاب به عنوان کارمند نمونه',
      isTop: 'کارمند نمونه منتخب',
      currentTop: 'کارمند نمونه فعلی',
      removeTop: 'حذف انتخاب',
      itemPlaceholder: 'مثلاً: پیگیری تیکت شماره ۱۲۴ یا جلسه با مشتری...',
      date: 'تاریخ گزارش',
      locked: 'زمان ویرایش پایان یافته'
    },
    en: {
      header: 'Performance Reporting',
      sub: 'Linear activity logging and smart aggregation',
      tabs: { daily: 'Daily', weekly: 'Weekly', monthly: 'Monthly' },
      new: 'Add Performance Report',
      edit: 'Edit Report',
      filterUser: 'View reports for:',
      tasks: 'Activity List (Linear Report)',
      addTask: 'Add Line',
      content: 'Notes & Blockers',
      save: 'Submit Report',
      update: 'Update Report',
      cancel: 'Cancel',
      empty: 'No reports found for this user.',
      topPerformer: 'Set as Top Performer',
      isTop: 'Selected Top Performer',
      currentTop: 'Top Performer',
      removeTop: 'Clear Selection',
      itemPlaceholder: 'e.g., Followed up on Ticket #124...',
      date: 'Report Date',
      locked: 'Editing Period Ended'
    }
  }[lang];

  const filteredReports = useMemo(() => {
    return reports.filter(r => r.userId === filterUserId && r.type === activeTab);
  }, [reports, filterUserId, activeTab]);

  const handleAddTask = () => {
    if (!currentTask.trim()) return;
    setTempTasks([...tempTasks, currentTask.trim()]);
    setCurrentTask('');
  };

  const handleOpenEdit = (report: PerformanceReport) => {
      setEditingReportId(report.id);
      setNewContent(report.content);
      setTempTasks(report.completedTasks);
      setReportDate(report.date);
      setShowAddModal(true);
  };

  const handleSaveReport = async () => {
    if (tempTasks.length === 0 && !newContent.trim()) return;

    if (editingReportId) {
        await updateReport(editingReportId, {
            content: newContent,
            completedTasks: tempTasks,
            date: reportDate,
            updatedAt: new Date().toISOString()
        }, currentUser.fullName);
    } else {
        const report: PerformanceReport = {
            id: `rep-${Date.now()}`,
            userId: currentUser.id,
            userName: currentUser.fullName,
            type: activeTab,
            date: reportDate,
            content: newContent,
            completedTasks: tempTasks,
            status: 'submitted',
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString()
        };

        await saveReport(report);

        if (activeTab === 'daily') {
            const weekKey = getWeekKey(new Date(reportDate));
            const monthKey = reportDate.slice(0, 7);
            await autoUpdateAggregatedReport(weekKey, 'weekly', report);
            await autoUpdateAggregatedReport(monthKey, 'monthly', report);
        }
    }

    handleCloseModal();
  };

  const handleCloseModal = () => {
      setShowAddModal(false);
      setEditingReportId(null);
      setTempTasks([]);
      setNewContent('');
  };

  const getWeekKey = (date: Date) => {
    const firstDayOfYear = new Date(date.getFullYear(), 0, 1);
    const pastDaysOfYear = (date.getTime() - firstDayOfYear.getTime()) / 86400000;
    return `${date.getFullYear()}-W${Math.ceil((pastDaysOfYear + firstDayOfYear.getDay() + 1) / 7)}`;
  };

  const autoUpdateAggregatedReport = async (dateKey: string, type: ReportType, sourceDaily: PerformanceReport) => {
      const existing = reports.find(r => r.userId === currentUser.id && r.type === type && r.date === dateKey);
      const summaryText = `[${sourceDaily.date}]: ${sourceDaily.completedTasks.join(' | ')}`;

      if (existing) {
          const updatedTasks = [...existing.completedTasks, ...sourceDaily.completedTasks];
          const updatedContent = existing.content + "\n" + summaryText;
          await updateReport(existing.id, { 
              completedTasks: updatedTasks, 
              content: updatedContent,
              updatedAt: new Date().toISOString() 
          }, 'System');
      } else {
          const newAggReport: PerformanceReport = {
              id: `agg-${Date.now()}-${Math.random()}`,
              userId: currentUser.id,
              userName: currentUser.fullName,
              type,
              date: dateKey,
              content: `تجمیع خودکار:\n${summaryText}`,
              completedTasks: sourceDaily.completedTasks,
              status: 'submitted',
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString()
          };
          await saveReport(newAggReport);
      }
  };

  const handleSetTopPerformer = async (userId: string) => {
    if (!isMaster) return;
    await saveAppConfigToCloud({ ...config, topPerformerId: userId });
    alert(lang === 'fa' ? 'کارمند نمونه با موفقیت تغییر یافت.' : 'Top performer updated successfully.');
  };

  const handleClearTopPerformer = async () => {
      if (!isMaster) return;
      await saveAppConfigToCloud({ ...config, topPerformerId: null });
      alert(lang === 'fa' ? 'انتخاب کارمند نمونه لغو شد.' : 'Top performer selection cleared.');
  };

  return (
    <div className="space-y-6 animate-fade-in">
        <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-2xl border border-gray-100 shadow-sm gap-4">
            <div className="flex items-center gap-4">
                <div className="bg-indigo-100 text-indigo-600 p-3 rounded-xl"><IconClipboard className="w-6 h-6" /></div>
                <div>
                    <h2 className="text-xl font-bold text-gray-800">{t.header}</h2>
                    <p className="text-sm text-gray-500">{t.sub}</p>
                </div>
            </div>
            <div className="flex gap-2">
                <div className="flex bg-gray-100 p-1 rounded-xl">
                    {(['daily', 'weekly', 'monthly'] as ReportType[]).map(tab => (
                        <button key={tab} onClick={() => setActiveTab(tab)} className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === tab ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>{t.tabs[tab]}</button>
                    ))}
                </div>
                <button onClick={() => { setEditingReportId(null); setShowAddModal(true); }} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-indigo-700 flex items-center gap-2 shadow-lg shadow-indigo-200">
                    <IconPlus className="w-5 h-5" /> {t.new}
                </button>
            </div>
        </div>

        <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="flex items-center gap-3">
                <IconSearch className="w-5 h-5 text-gray-400" />
                <label className="text-sm font-bold text-gray-700">{t.filterUser}</label>
                <select 
                    className="outline-none bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-200 text-sm"
                    value={filterUserId}
                    onChange={(e) => setFilterUserId(e.target.value)}
                >
                    {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                </select>
            </div>
            {isMaster && config.topPerformerId && (
                <div className="flex items-center gap-3 bg-amber-50 text-amber-700 px-3 py-1.5 rounded-lg border border-amber-100 text-sm font-bold">
                    <div className="flex items-center gap-2">
                        <IconAward className="w-4 h-4" />
                        {t.currentTop}: {personnel.find(p => p.id === config.topPerformerId)?.fullName}
                    </div>
                    <button onClick={handleClearTopPerformer} className="p-1 hover:bg-amber-200 rounded-full transition-colors text-amber-500 hover:text-amber-700" title={t.removeTop}>✕</button>
                </div>
            )}
        </div>

        <div className="grid grid-cols-1 gap-4">
            {filteredReports.map(report => {
                const isOwnReport = report.userId === currentUser.id;
                const isToday = report.date === todayStr;
                const canEdit = isMaster || (isOwnReport && isToday);

                return (
                    <div key={report.id} className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm hover:shadow-md transition-all group">
                        <div className="flex justify-between items-start mb-4">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-full bg-indigo-50 flex items-center justify-center text-indigo-600 font-bold">{report.userName.charAt(0)}</div>
                                <div>
                                    <div className="font-bold text-gray-900">{report.userName}</div>
                                    <div className="text-xs text-gray-400 font-mono">{report.date}</div>
                                </div>
                            </div>
                            <div className="flex items-center gap-2">
                                {isMaster && (
                                    <button 
                                        onClick={() => handleSetTopPerformer(report.userId)} 
                                        className={`opacity-0 group-hover:opacity-100 px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1 transition-all ${config.topPerformerId === report.userId ? 'bg-amber-500 text-white shadow-sm' : 'bg-amber-100 text-amber-700 hover:bg-amber-200'}`}
                                    >
                                        <IconAward className="w-4 h-4" /> {config.topPerformerId === report.userId ? t.isTop : t.topPerformer}
                                    </button>
                                )}

                                {canEdit ? (
                                    <button 
                                        onClick={() => handleOpenEdit(report)}
                                        className="opacity-0 group-hover:opacity-100 bg-blue-100 text-blue-700 px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1 transition-all hover:bg-blue-200"
                                    >
                                        <IconEdit className="w-4 h-4" /> {t.edit}
                                    </button>
                                ) : (
                                    isOwnReport && (
                                        <span className="text-[10px] text-gray-300 flex items-center gap-1 bg-gray-50 px-2 py-1 rounded">
                                            <IconLock className="w-3 h-3" /> {t.locked}
                                        </span>
                                    )
                                )}

                                <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-1 rounded">{new Date(report.createdAt).toLocaleTimeString()}</span>
                            </div>
                        </div>

                        <div className="space-y-4">
                            <div>
                                <h4 className="text-xs font-bold text-gray-400 mb-2 uppercase tracking-wider flex items-center gap-1"><IconList className="w-3 h-3" /> {t.tasks}</h4>
                                <div className="space-y-2">
                                    {report.completedTasks.map((task, i) => (
                                        <div key={i} className="flex items-center gap-3 text-sm text-gray-700 bg-gray-50/50 p-3 rounded-xl border border-gray-100">
                                            <div className="w-5 h-5 rounded-full bg-green-100 text-green-600 flex items-center justify-center shrink-0 font-bold text-[10px]">{i+1}</div>
                                            {task}
                                        </div>
                                    ))}
                                </div>
                            </div>
                            {report.content && (
                                <div className="pt-4 border-t border-gray-50">
                                    <h4 className="text-xs font-bold text-gray-400 mb-1 uppercase tracking-wider">{t.content}</h4>
                                    <p className="text-sm text-gray-600 whitespace-pre-wrap leading-relaxed">{report.content}</p>
                                </div>
                            )}
                            {report.updatedAt !== report.createdAt && (
                                <div className="text-[10px] text-gray-400 mt-2 italic">
                                    آخرین ویرایش: {new Date(report.updatedAt).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}
                                </div>
                            )}
                        </div>
                    </div>
                );
            })}
            {filteredReports.length === 0 && <div className="py-12 text-center text-gray-400 bg-white rounded-2xl border-2 border-dashed">{t.empty}</div>}
        </div>

        {/* Modal (Add/Edit) */}
        {showAddModal && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
                <div className="bg-white rounded-3xl w-full max-w-xl shadow-2xl animate-fade-in overflow-hidden flex flex-col max-h-[90vh]">
                    <div className="p-6 border-b border-gray-100 bg-indigo-50 flex justify-between items-center">
                        <h3 className="font-bold text-indigo-900 text-lg flex items-center gap-2">
                           {editingReportId ? <IconEdit className="w-5 h-5" /> : <IconPlus className="w-5 h-5" />}
                           {editingReportId ? t.edit : t.new} ({t.tabs[activeTab]})
                        </h3>
                        <button onClick={handleCloseModal} className="text-gray-400 hover:text-gray-600">✕</button>
                    </div>
                    <div className="p-6 overflow-y-auto space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 mb-1">{t.date}</label>
                                <input 
                                    type="date" 
                                    className="w-full border rounded-xl p-2.5 outline-none focus:ring-2 focus:ring-indigo-500 disabled:bg-gray-50 disabled:text-gray-400" 
                                    value={reportDate} 
                                    onChange={e => setReportDate(e.target.value)} 
                                    disabled={!isMaster && editingReportId !== null} // Only master can change date during edit
                                />
                            </div>
                        </div>

                        <div className="bg-gray-50 p-4 rounded-2xl border border-gray-200">
                            <label className="block text-sm font-bold text-gray-700 mb-3 flex items-center gap-2">
                                <IconList className="w-4 h-4 text-indigo-600" />
                                {t.tasks}
                            </label>
                            <div className="space-y-2 mb-4">
                                {tempTasks.map((task, i) => (
                                    <div key={i} className="flex items-center gap-2 bg-white p-3 rounded-xl border border-gray-200 shadow-sm group">
                                        <span className="w-6 h-6 rounded-full bg-gray-100 flex items-center justify-center text-[10px] font-bold text-gray-500 shrink-0">{i+1}</span>
                                        <span className="flex-grow text-sm text-gray-700">{task}</span>
                                        <button onClick={() => setTempTasks(tempTasks.filter((_, idx) => idx !== i))} className="text-red-400 hover:text-red-600 p-1 opacity-0 group-hover:opacity-100 transition-opacity"><IconTrash className="w-4 h-4" /></button>
                                    </div>
                                ))}
                            </div>
                            <div className="flex gap-2">
                                <input 
                                    className="flex-grow border border-gray-300 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-indigo-500 bg-white" 
                                    placeholder={t.itemPlaceholder} 
                                    value={currentTask} 
                                    onChange={e => setCurrentTask(e.target.value)} 
                                    onKeyDown={e => e.key === 'Enter' && (e.preventDefault(), handleAddTask())}
                                />
                                <button onClick={handleAddTask} className="bg-indigo-600 text-white px-4 rounded-xl font-bold hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-100">{t.addTask}</button>
                            </div>
                        </div>

                        <div>
                            <label className="block text-xs font-bold text-gray-500 mb-1">{t.content}</label>
                            <textarea 
                                className="w-full border rounded-xl p-3 text-sm outline-none focus:ring-2 focus:ring-indigo-500" 
                                rows={3} 
                                value={newContent} 
                                onChange={e => setNewContent(e.target.value)}
                            />
                        </div>
                    </div>
                    <div className="p-4 bg-gray-50 border-t flex gap-3">
                        <button onClick={handleCloseModal} className="flex-1 py-3 text-gray-600 font-bold hover:bg-gray-100 rounded-xl transition-colors">{t.cancel}</button>
                        <button onClick={handleSaveReport} className="flex-1 py-3 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-200">
                            {editingReportId ? t.update : t.save}
                        </button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useRef, useMemo } from 'react';
import { InternalMessage, Personnel, AttachedFile } from '../types';
import { IconMail, IconSend, IconInbox, IconPaperclip, IconTrash, IconFile, IconCheck, IconReply, IconPlus, IconSearch, IconUsers, IconArrowRight } from './Icons';
import { sendInternalMessage, updateMessageInCloud, deleteMessageFromCloud, uploadFileWithProgress } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  messages: InternalMessage[];
  lang: Language;
}

export const InternalMessenger: React.FC<Props> = ({ currentUser, personnel, messages, lang }) => {
  const [activeTab, setActiveTab] = useState<'inbox' | 'sent'>('inbox');
  const [selectedMessage, setSelectedMessage] = useState<InternalMessage | null>(null);
  const [isComposeOpen, setIsComposeOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Compose State
  const [recipientIds, setRecipientIds] = useState<string[]>([]);
  const [subject, setSubject] = useState('');
  const [body, setBody] = useState('');
  const [attachments, setAttachments] = useState<AttachedFile[]>([]);
  const [isSending, setIsSending] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isMaster = currentUser.username === 'master';

  const t = {
      fa: {
          inbox: 'صندوق ورودی',
          sent: 'پیام‌های ارسالی',
          compose: 'پیام جدید',
          search: 'جستجو در پیام‌ها...',
          subject: 'موضوع',
          body: 'متن پیام',
          recipients: 'گیرندگان',
          send: 'ارسال پیام',
          sending: 'در حال ارسال...',
          reply: 'پاسخ',
          replyAll: 'پاسخ به همه',
          delete: 'حذف',
          close: 'بستن',
          attach: 'افزودن فایل',
          emptyInbox: 'صندوق ورودی شما خالی است.',
          emptySent: 'هیچ پیامی ارسال نکرده‌اید.',
          success: 'پیام با موفقیت ارسال شد.',
          error: 'خطا در ارسال پیام.',
          to: 'به:',
          from: 'از طرف:',
          date: 'تاریخ:',
          uploading: 'آپلود...',
          writeHere: 'متن پیام خود را بنویسید...',
          selectUser: 'انتخاب گیرندگان',
          files: 'فایل‌های پیوست'
      },
      en: {
          inbox: 'Inbox',
          sent: 'Sent',
          compose: 'New Message',
          search: 'Search messages...',
          subject: 'Subject',
          body: 'Message Body',
          recipients: 'Recipients',
          send: 'Send Message',
          sending: 'Sending...',
          reply: 'Reply',
          replyAll: 'Reply All',
          delete: 'Delete',
          close: 'Close',
          attach: 'Attach File',
          emptyInbox: 'Your inbox is empty.',
          emptySent: 'No sent messages.',
          success: 'Message sent successfully.',
          error: 'Error sending message.',
          to: 'To:',
          from: 'From:',
          date: 'Date:',
          uploading: 'Uploading...',
          writeHere: 'Write your message...',
          selectUser: 'Select Recipients',
          files: 'Attachments'
      }
  }[lang];

  // Filter Messages
  const filteredMessages = useMemo(() => {
      let list = activeTab === 'inbox' 
          ? messages.filter(m => m.recipientIds.includes(currentUser.id))
          : messages.filter(m => m.senderId === currentUser.id);

      // Sort by date desc
      list = list.sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

      if (searchTerm.trim()) {
          const lowerTerm = searchTerm.toLowerCase();
          list = list.filter(m => 
              m.subject.toLowerCase().includes(lowerTerm) || 
              m.body.toLowerCase().includes(lowerTerm) ||
              m.senderName.toLowerCase().includes(lowerTerm)
          );
      }
      return list;
  }, [messages, activeTab, currentUser.id, searchTerm]);

  const handleSendMessage = async () => {
      if (recipientIds.length === 0 || !subject.trim() || !body.trim()) { 
          alert(lang === 'fa' ? 'لطفا گیرنده، موضوع و متن را وارد کنید.' : 'Please fill all fields.'); 
          return; 
      }
      if (attachments.some(f => f.status === 'uploading')) { 
          alert(lang === 'fa' ? 'لطفا صبر کنید تا فایل‌ها آپلود شوند.' : 'Please wait for uploads.'); 
          return; 
      }

      setIsSending(true);
      try {
          const recipientNames = recipientIds.map(id => personnel.find(p => p.id === id)?.fullName || 'Unknown');
          const newMessage: InternalMessage = { 
              id: `msg-${Date.now()}`, 
              senderId: currentUser.id, 
              senderName: currentUser.fullName, 
              senderAvatar: currentUser.avatar, 
              recipientIds: recipientIds, 
              recipientNames: recipientNames, 
              subject: subject, 
              body: body, 
              files: attachments.filter(f => f.status === 'success'), 
              createdAt: new Date().toISOString(), 
              readBy: [] 
          };

          await sendInternalMessage(newMessage);
          resetCompose();
          setIsComposeOpen(false);
          setActiveTab('sent');
          alert(t.success);
      } catch (e) { 
          alert(t.error); 
      } finally { 
          setIsSending(false); 
      }
  };

  const handleMessageClick = (msg: InternalMessage) => {
      setSelectedMessage(msg);
      // Mark as read if in inbox
      if (activeTab === 'inbox' && !msg.readBy.includes(currentUser.id)) {
          const updatedReadBy = [...msg.readBy, currentUser.id];
          updateMessageInCloud(msg.id, { readBy: updatedReadBy });
      }
  };

  const handleDeleteMessage = async (id: string) => {
      if (window.confirm(lang === 'fa' ? 'آیا مطمئن هستید؟' : 'Are you sure?')) {
          await deleteMessageFromCloud(id);
          if (selectedMessage?.id === id) {
              setSelectedMessage(null);
          }
      }
  };

  const handleReply = (msg: InternalMessage, replyAll: boolean = false) => {
      let recIds = [msg.senderId];
      if (replyAll) {
          const others = msg.recipientIds.filter(id => id !== currentUser.id);
          recIds = Array.from(new Set([msg.senderId, ...others]));
      }
      setRecipientIds(recIds);

      const cleanSubject = msg.subject.replace(/^(Re:|پاسخ:)\s*/i, '');
      setSubject(`${lang === 'fa' ? 'پاسخ:' : 'Re:'} ${cleanSubject}`);

      const quoteHeader = `\n\n\n--------------------------------------------------\n${t.from} ${msg.senderName} | ${new Date(msg.createdAt).toLocaleString()}`;
      const quotedBody = msg.body.split('\n').map(line => `> ${line}`).join('\n');
      setBody(`${quoteHeader}\n${quotedBody}`);

      setSelectedMessage(null); // Close view modal
      setIsComposeOpen(true); // Open compose modal
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) {
          const file = e.target.files[0];
          if (file.size > 5 * 1024 * 1024) { alert('Max 5MB'); return; }

          const newFile: AttachedFile = { name: file.name, size: file.size, type: file.type, content: '', status: 'uploading', progress: 0 };
          setAttachments(prev => [...prev, newFile]);

          uploadFileWithProgress(
              file,
              (progress) => setAttachments(prev => prev.map(f => f.name === file.name && f.status === 'uploading' ? { ...f, progress } : f)),
              (url) => setAttachments(prev => prev.map(f => f.name === file.name ? { ...f, content: url, status: 'success', progress: 100 } : f)),
              (err) => setAttachments(prev => prev.map(f => f.name === file.name ? { ...f, status: 'error', errorMsg: err.message } : f))
          );
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const resetCompose = () => {
      setRecipientIds([]); setSubject(''); setBody(''); setAttachments([]);
  };

  const toggleRecipient = (id: string) => {
      setRecipientIds(prev => prev.includes(id) ? prev.filter(uid => uid !== id) : [...prev, id]);
  };

  return (
    <div className="bg-white rounded-3xl border border-gray-100 shadow-lg min-h-[600px] flex flex-col relative animate-fade-in overflow-hidden w-full max-w-full">
        {/* --- Header / Toolbar --- */}
        <div className="p-4 border-b border-gray-100 bg-white sticky top-0 z-10 flex flex-col md:flex-row justify-between items-center gap-4 w-full">
            {/* Tabs */}
            <div className="flex bg-gray-100 p-1 rounded-xl w-full md:w-auto shrink-0">
                <button 
                    onClick={() => setActiveTab('inbox')} 
                    className={`flex-1 md:flex-none px-6 py-2 rounded-lg text-sm font-bold transition-all flex items-center justify-center gap-2 ${activeTab === 'inbox' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <IconInbox className="w-4 h-4" /> {t.inbox}
                </button>
                <button 
                    onClick={() => setActiveTab('sent')} 
                    className={`flex-1 md:flex-none px-6 py-2 rounded-lg text-sm font-bold transition-all flex items-center justify-center gap-2 ${activeTab === 'sent' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <IconSend className="w-4 h-4" /> {t.sent}
                </button>
            </div>

            {/* Actions */}
            <div className="flex w-full md:w-auto gap-3 shrink-0">
                <div className="relative flex-grow md:flex-grow-0 md:w-64">
                    <input 
                        className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border border-transparent focus:bg-white focus:border-indigo-200 rounded-xl text-sm outline-none transition-all" 
                        placeholder={t.search}
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                    <IconSearch className="w-4 h-4 text-gray-400 absolute left-3 top-3" />
                </div>
                <button 
                    onClick={() => { resetCompose(); setIsComposeOpen(true); }}
                    className="bg-indigo-600 text-white px-4 py-2.5 rounded-xl font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-200 flex items-center gap-2 transition-transform active:scale-95 whitespace-nowrap"
                >
                    <IconPlus className="w-5 h-5" /> <span className="hidden md:inline">{t.compose}</span>
                </button>
            </div>
        </div>

        {/* --- Message List --- */}
        <div className="flex-grow overflow-y-auto p-2 md:p-4 bg-gray-50/50 w-full">
            {filteredMessages.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-full text-gray-400 py-12">
                    <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mb-4 text-gray-300">
                        <IconMail className="w-10 h-10" />
                    </div>
                    <p className="font-medium">{activeTab === 'inbox' ? t.emptyInbox : t.emptySent}</p>
                </div>
            ) : (
                <div className="space-y-2 w-full">
                    {filteredMessages.map(msg => {
                        const isUnread = activeTab === 'inbox' && !msg.readBy.includes(currentUser.id);
                        // Summary: Clean body text for preview: remove newlines and limit length
                        const bodyPreview = msg.body.replace(/\n/g, ' ').substring(0, 100);

                        return (
                            <div 
                                key={msg.id}
                                onClick={() => handleMessageClick(msg)}
                                className={`group p-4 rounded-2xl cursor-pointer border transition-all hover:shadow-md flex items-center gap-4 relative overflow-hidden w-full max-w-full
                                    ${isUnread ? 'bg-white border-indigo-200 shadow-sm' : 'bg-white border-gray-100 opacity-90 hover:opacity-100'}
                                `}
                            >
                                {isUnread && <div className="absolute top-0 right-0 w-2 h-full bg-indigo-500"></div>}

                                <div className={`w-10 h-10 md:w-12 md:h-12 rounded-full flex items-center justify-center text-white font-bold shrink-0 shadow-sm
                                    ${activeTab === 'inbox' ? 'bg-gradient-to-br from-indigo-400 to-purple-500' : 'bg-gray-400'}
                                `}>
                                    {activeTab === 'inbox' ? msg.senderName.charAt(0) : <IconSend className="w-5 h-5" />}
                                </div>

                                <div className="flex-grow min-w-0">
                                    <div className="flex justify-between items-center mb-1 gap-2">
                                        <h4 className={`text-sm truncate shrink-0 ${isUnread ? 'font-black text-gray-900' : 'font-bold text-gray-700'}`}>
                                            {activeTab === 'inbox' ? msg.senderName : msg.recipientNames.join(', ')}
                                        </h4>
                                        <span className={`text-[10px] whitespace-nowrap ${isUnread ? 'text-indigo-600 font-bold' : 'text-gray-400'} dir-ltr`}>
                                            {new Date(msg.createdAt).toLocaleDateString(lang === 'fa' ? 'fa-IR' : 'en-US')}
                                        </span>
                                    </div>
                                    <div className="flex items-center justify-between gap-4">
                                        <p className={`text-xs truncate max-w-full overflow-hidden ${isUnread ? 'text-gray-800 font-medium' : 'text-gray-500'}`}>
                                            <span className="font-bold">{msg.subject}</span>
                                            <span className="text-gray-300 mx-2">|</span>
                                            <span className="font-normal opacity-70">{bodyPreview}</span>
                                        </p>
                                        {msg.files && msg.files.length > 0 && <IconPaperclip className="w-3 h-3 text-gray-400 shrink-0" />}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>

        {/* --- View Message Modal (Dialog) --- */}
        {selectedMessage && (
            <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setSelectedMessage(null)}>
                <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]" onClick={e => e.stopPropagation()}>
                    {/* Modal Header */}
                    <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50 shrink-0">
                        <div className="flex items-center gap-3 min-w-0">
                            <div className="w-10 h-10 rounded-full bg-gradient-to-r from-blue-500 to-indigo-600 flex items-center justify-center text-white font-bold shadow-md shrink-0">
                                {selectedMessage.senderName.charAt(0)}
                            </div>
                            <div className="min-w-0">
                                <h3 className="font-bold text-gray-900 text-lg leading-tight truncate">{selectedMessage.subject}</h3>
                                <div className="text-xs text-gray-500 flex items-center gap-1">
                                    <span className="whitespace-nowrap">{activeTab === 'inbox' ? t.from : t.to}</span>
                                    <span className="font-medium text-gray-700 truncate">{activeTab === 'inbox' ? selectedMessage.senderName : selectedMessage.recipientNames.join(', ')}</span>
                                    <span className="w-1 h-1 bg-gray-300 rounded-full mx-1 shrink-0"></span>
                                    <span className="dir-ltr whitespace-nowrap">{new Date(selectedMessage.createdAt).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</span>
                                </div>
                            </div>
                        </div>
                        <button onClick={() => setSelectedMessage(null)} className="p-2 hover:bg-gray-200 rounded-full text-gray-500 transition-colors shrink-0">✕</button>
                    </div>

                    {/* Modal Content */}
                    <div className="p-6 md:p-8 overflow-y-auto flex-grow bg-white">
                        <div className="prose prose-sm max-w-none text-gray-700 leading-relaxed whitespace-pre-wrap font-light text-base break-words">
                            {selectedMessage.body}
                        </div>

                        {selectedMessage.files && selectedMessage.files.length > 0 && (
                            <div className="mt-8 pt-6 border-t border-gray-100">
                                <h4 className="text-xs font-bold text-gray-500 mb-3 flex items-center gap-2 uppercase tracking-wider">
                                    <IconPaperclip className="w-4 h-4" /> {t.files}
                                </h4>
                                <div className="flex flex-wrap gap-3">
                                    {selectedMessage.files.map((f, i) => (
                                        <a key={i} href={f.content} target="_blank" rel="noreferrer" className="flex items-center gap-3 p-3 bg-gray-50 border border-gray-200 rounded-xl hover:bg-indigo-50 hover:border-indigo-200 transition-all group min-w-[150px] max-w-full">
                                            <div className="p-2 bg-white rounded-lg shadow-sm text-indigo-500 group-hover:scale-110 transition-transform"><IconFile className="w-5 h-5" /></div>
                                            <div className="truncate">
                                                <div className="text-sm font-bold text-gray-700 group-hover:text-indigo-700 truncate">{f.name}</div>
                                                <div className="text-[10px] text-gray-400">{(f.size / 1024).toFixed(0)} KB</div>
                                            </div>
                                        </a>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Modal Footer (Actions) */}
                    <div className="p-4 bg-gray-50 border-t border-gray-100 flex justify-between items-center shrink-0">
                        {isMaster && (
                            <button onClick={() => handleDeleteMessage(selectedMessage.id)} className="text-red-500 hover:bg-red-50 px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-colors">
                                <IconTrash className="w-4 h-4" /> {t.delete}
                            </button>
                        )}
                        <div className="flex gap-3 ml-auto">
                            <button onClick={() => handleReply(selectedMessage, true)} className="bg-white border border-gray-200 text-gray-700 hover:bg-gray-100 px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-colors shadow-sm">
                                <IconUsers className="w-4 h-4" /> {t.replyAll}
                            </button>
                            <button onClick={() => handleReply(selectedMessage)} className="bg-indigo-600 text-white hover:bg-indigo-700 px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-colors shadow-lg shadow-indigo-200">
                                <IconReply className="w-4 h-4" /> {t.reply}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* --- Compose Modal --- */}
        {isComposeOpen && (
            <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm animate-scale-in">
                <div className="bg-white w-full max-w-3xl rounded-3xl shadow-2xl flex flex-col max-h-[90vh] overflow-hidden">
                    <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50 shrink-0">
                        <h3 className="font-bold text-gray-800 text-lg flex items-center gap-2">
                            <div className="p-1.5 bg-indigo-100 text-indigo-600 rounded-lg"><IconPlus className="w-5 h-5" /></div>
                            {t.compose}
                        </h3>
                        <button onClick={() => setIsComposeOpen(false)} className="text-gray-400 hover:text-gray-600">✕</button>
                    </div>

                    <div className="flex-grow overflow-y-auto p-6 space-y-6">
                        {/* Recipients Selector */}
                        <div>
                            <label className="block text-xs font-bold text-gray-500 mb-2">{t.recipients}</label>
                            <div className="flex flex-wrap gap-2 p-3 bg-gray-50 border border-gray-200 rounded-xl max-h-32 overflow-y-auto">
                                {personnel.filter(p => p.id !== currentUser.id).map(p => (
                                    <button 
                                        key={p.id} 
                                        onClick={() => toggleRecipient(p.id)}
                                        className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-bold border transition-all ${
                                            recipientIds.includes(p.id) 
                                                ? 'bg-indigo-600 text-white border-indigo-600 shadow-md transform scale-105' 
                                                : 'bg-white text-gray-600 border-gray-200 hover:border-indigo-300'
                                        }`}
                                    >
                                        <div className={`w-5 h-5 rounded-full flex items-center justify-center text-[9px] ${recipientIds.includes(p.id) ? 'bg-white text-indigo-600' : 'bg-gray-100'}`}>
                                            {p.fullName.charAt(0)}
                                        </div>
                                        {p.fullName}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Subject */}
                        <div>
                            <input 
                                className="w-full px-0 py-2 text-lg font-bold text-gray-800 placeholder-gray-400 border-b-2 border-gray-100 focus:border-indigo-500 outline-none transition-colors bg-transparent"
                                placeholder={t.subject}
                                value={subject}
                                onChange={e => setSubject(e.target.value)}
                                autoFocus
                            />
                        </div>

                        {/* Body */}
                        <textarea 
                            className="w-full h-64 p-4 text-gray-700 bg-gray-50 rounded-2xl border-none outline-none focus:ring-2 focus:ring-indigo-100 resize-none text-base leading-relaxed"
                            placeholder={t.writeHere}
                            value={body}
                            onChange={e => setBody(e.target.value)}
                        />

                        {/* Attachments List */}
                        {attachments.length > 0 && (
                            <div className="flex flex-wrap gap-3">
                                {attachments.map((f, i) => (
                                    <div key={i} className={`flex items-center gap-2 px-3 py-2 rounded-xl border text-sm ${f.status === 'error' ? 'bg-red-50 border-red-200 text-red-600' : 'bg-white border-gray-200 text-gray-700'}`}>
                                        <IconFile className="w-4 h-4 opacity-50" />
                                        <span className="truncate max-w-[150px]">{f.name}</span>
                                        {f.status === 'uploading' && <span className="text-xs text-indigo-500 font-bold">{Math.round(f.progress || 0)}%</span>}
                                        <button onClick={() => setAttachments(prev => prev.filter((_, idx) => idx !== i))} className="hover:text-red-500 ml-1">✕</button>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    <div className="p-4 border-t border-gray-100 flex justify-between items-center bg-white shrink-0">
                        <button onClick={() => fileInputRef.current?.click()} className="text-gray-500 hover:text-indigo-600 font-bold text-sm flex items-center gap-2 px-4 py-2 rounded-xl hover:bg-gray-50 transition-colors">
                            <IconPaperclip className="w-5 h-5" /> {t.attach}
                        </button>
                        <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileSelect} accept="image/*,.pdf" multiple />

                        <div className="flex gap-3">
                            <button onClick={() => setIsComposeOpen(false)} className="px-6 py-2 rounded-xl text-gray-600 font-bold hover:bg-gray-100 transition-colors">{t.cancel}</button>
                            <button onClick={handleSendMessage} disabled={isSending} className="bg-indigo-600 text-white px-8 py-2 rounded-xl font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700 hover:scale-105 transition-all disabled:opacity-50 flex items-center gap-2">
                                {isSending ? t.sending : <><IconSend className="w-4 h-4" /> {t.send}</>}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useRef, useMemo } from 'react';
import { InternalMessage, Personnel, AttachedFile } from '../types';
import { IconMail, IconSend, IconInbox, IconPaperclip, IconTrash, IconFile, IconCheck, IconReply, IconPlus, IconSearch, IconUsers, IconArrowRight } from './Icons';
import { sendInternalMessage, updateMessageInCloud, deleteMessageFromCloud, uploadFileWithProgress } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  messages: InternalMessage[];
  lang: Language;
}

export const InternalMessenger: React.FC<Props> = ({ currentUser, personnel, messages, lang }) => {
  const [activeTab, setActiveTab] = useState<'inbox' | 'sent'>('inbox');
  const [selectedMessage, setSelectedMessage] = useState<InternalMessage | null>(null);
  const [isComposeOpen, setIsComposeOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Compose State
  const [recipientIds, setRecipientIds] = useState<string[]>([]);
