      fa: {
          inbox: 'صندوق ورودی',
          sent: 'پیام‌های ارسالی',
          compose: 'پیام جدید',
          search: 'جستجو...',
          subject: 'موضوع',
          body: 'متن پیام',
          recipients: 'گیرندگان',
          send: 'ارسال پیام',
          sending: 'در حال ارسال...',
          reply: 'پاسخ',
          replyAll: 'پاسخ به همه',
          delete: 'حذف',
          close: 'بستن',
          attach: 'افزودن فایل',
          emptyInbox: 'صندوق ورودی خالی است.',
          emptySent: 'پیامی ارسال نشده است.',
          success: 'ارسال شد.',
          error: 'خطا!',
          to: 'به:',
          from: 'از:',
          date: 'تاریخ:',
          uploading: 'آپلود...',
          writeHere: 'متن پیام...',
          selectUser: 'انتخاب گیرندگان',
          files: 'پیوست‌ها',
          cancel: 'انصراف'
      },
      en: {
          inbox: 'Inbox',
          sent: 'Sent',
          compose: 'New Message',
          search: 'Search...',
          subject: 'Subject',
          body: 'Message',
          recipients: 'Recipients',
          send: 'Send',
          sending: 'Sending...',
          reply: 'Reply',
          replyAll: 'Reply All',
          delete: 'Delete',
          close: 'Close',
          attach: 'Attach',
          emptyInbox: 'Empty inbox.',
          emptySent: 'No sent messages.',
          success: 'Sent successfully.',
          error: 'Error!',
          to: 'To:',
          from: 'From:',
          date: 'Date:',
          uploading: 'Uploading...',
          writeHere: 'Write message...',
          selectUser: 'Recipients',
          files: 'Attachments',
          cancel: 'Cancel'
      }
  }[lang];

  const filteredMessages = useMemo(() => {
      let list = activeTab === 'inbox' 
          ? messages.filter(m => m.recipientIds.includes(currentUser.id))
          : messages.filter(m => m.senderId === currentUser.id);

      list = [...list].sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

      if (searchTerm.trim()) {
          const term = searchTerm.toLowerCase();
          list = list.filter(m => 
              m.subject.toLowerCase().includes(term) || 
              m.body.toLowerCase().includes(term) ||
              m.senderName.toLowerCase().includes(term)
          );
      }
      return list;
  }, [messages, activeTab, currentUser.id, searchTerm]);

  const handleSendMessage = async () => {
      if (recipientIds.length === 0 || !subject.trim() || !body.trim()) return;
      setIsSending(true);
      try {
          const recipientNames = recipientIds.map(id => personnel.find(p => p.id === id)?.fullName || 'Unknown');
