        <div className="flex-grow overflow-y-auto bg-gray-50/30 overflow-x-hidden max-w-full">
            {filteredMessages.length === 0 ? (
                <div className="py-20 text-center text-gray-400 text-sm">{activeTab === 'inbox' ? t.emptyInbox : t.emptySent}</div>
