                <div className="divide-y divide-gray-50">
                    {filteredMessages.map(msg => {
                        const isUnread = activeTab === 'inbox' && !msg.readBy.includes(currentUser.id);
                        const cleanPreview = msg.body.replace(/[\n\r]/g, ' ').substring(0, 60);
                        return (
                            <div key={msg.id} onClick={() => handleMessageClick(msg)} className={`p-4 cursor-pointer transition-colors flex items-center gap-4 hover:bg-white relative min-w-0 w-full overflow-hidden ${isUnread ? 'bg-indigo-50/50' : 'bg-transparent'}`}>
                                {isUnread && <div className="absolute right-0 top-0 w-1 h-full bg-indigo-600"></div>}
                                <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white text-xs font-black shrink-0 ${activeTab === 'inbox' ? 'bg-indigo-500' : 'bg-gray-400'}`}>
                                    {activeTab === 'inbox' ? msg.senderName.charAt(0) : <IconSend className="w-4 h-4" />}
                                </div>
                                <div className="flex-grow min-w-0">
                                    <div className="flex justify-between items-center mb-0.5">
                                        <h4 className={`text-sm truncate pr-2 ${isUnread ? 'font-black text-gray-900' : 'font-bold text-gray-700'}`}>
                                            {activeTab === 'inbox' ? msg.senderName : msg.recipientNames.join(', ')}
                                        </h4>
                                        <span className="text-[10px] text-gray-400 whitespace-nowrap dir-ltr">
                                            {new Date(msg.createdAt).toLocaleDateString(lang === 'fa' ? 'fa-IR' : 'en-US')}
                                        </span>
                                    </div>
                                    <div className="flex items-center gap-2 min-w-0">
                                        <p className="text-xs text-gray-500 truncate flex-grow min-w-0">
                                            <span className={`font-bold ${isUnread ? 'text-indigo-700' : 'text-gray-800'}`}>{msg.subject}</span>
                                            <span className="mx-2 text-gray-300">|</span>
                                            <span className="opacity-70">{cleanPreview}...</span>
                                        </p>
                                        {msg.files && msg.files.length > 0 && <IconPaperclip className="w-3 h-3 text-gray-400 shrink-0" />}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>

        {/* --- View Message Modal --- */}
        {selectedMessage && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm" onClick={() => setSelectedMessage(null)}>
                <div className="bg-white w-full max-w-xl rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[85vh]" onClick={e => e.stopPropagation()}>
                    <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50 shrink-0">
                        <div className="min-w-0">
                            <h3 className="font-black text-gray-900 truncate">{selectedMessage.subject}</h3>
                            <div className="text-[10px] text-gray-500 flex items-center gap-1 mt-0.5">
                                <span className="font-bold">{activeTab === 'inbox' ? t.from : t.to} {activeTab === 'inbox' ? selectedMessage.senderName : selectedMessage.recipientNames.join(', ')}</span>
                                <span className="dir-ltr">{new Date(selectedMessage.createdAt).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</span>
                            </div>
                        </div>
                        <button onClick={() => setSelectedMessage(null)} className="p-2 hover:bg-gray-200 rounded-full text-gray-500">✕</button>
                    </div>
                    <div className="p-6 overflow-y-auto flex-grow text-sm text-gray-700 leading-relaxed whitespace-pre-wrap break-words">
                        {selectedMessage.body}
                        {selectedMessage.files && selectedMessage.files.length > 0 && (
                            <div className="mt-6 pt-4 border-t border-gray-100 grid grid-cols-2 gap-2">
                                {selectedMessage.files.map((f, i) => (
                                    <a key={i} href={f.content} target="_blank" rel="noreferrer" className="flex items-center gap-2 p-2 bg-gray-50 rounded-lg border border-gray-200 hover:bg-indigo-50 transition-colors truncate">
                                        <IconFile className="w-4 h-4 text-indigo-500 shrink-0" />
                                        <span className="text-[10px] font-bold truncate">{f.name}</span>
                                    </a>
                                ))}
                            </div>
                        )}
                    </div>
                    <div className="p-3 bg-gray-50 border-t border-gray-100 flex justify-end gap-2 shrink-0">
                        {isMaster && <button onClick={() => { if(confirm(lang==='fa'?'حذف؟':'Delete?')) { deleteMessageFromCloud(selectedMessage.id); setSelectedMessage(null); } }} className="ml-auto text-red-500 text-xs font-bold px-3 py-1.5 hover:bg-red-50 rounded-lg"><IconTrash className="w-4 h-4" /></button>}
                        <button onClick={() => { 
                            setRecipientIds([selectedMessage.senderId]); 
                            setSubject(`${lang==='fa'?'پاسخ:':'Re:'} ${selectedMessage.subject}`); 
                            setBody(`\n\n--- ${selectedMessage.senderName} ---\n> ${selectedMessage.body}`);
                            setSelectedMessage(null); 
                            setIsComposeOpen(true); 
                        }} className="bg-indigo-600 text-white px-4 py-1.5 rounded-lg text-xs font-bold hover:bg-indigo-700">{t.reply}</button>
                    </div>
                </div>
            </div>
        )}

        {/* --- Compose Modal --- */}
        {isComposeOpen && (
            <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm">
                <div className="bg-white w-full max-w-2xl rounded-2xl shadow-2xl flex flex-col max-h-[90vh] overflow-hidden">
                    <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-indigo-600 text-white shrink-0">
                        <h3 className="font-black text-sm flex items-center gap-2"><IconPlus className="w-4 h-4" /> {t.compose}</h3>
                        <button onClick={() => setIsComposeOpen(false)} className="hover:opacity-70">✕</button>
                    </div>
                    <div className="p-5 flex-grow overflow-y-auto space-y-4">
                        <div>
                            <label className="text-[10px] font-black text-gray-400 mb-1 block">{t.recipients}</label>
                            <div className="flex flex-wrap gap-1.5 p-2 bg-gray-50 border border-gray-200 rounded-xl max-h-24 overflow-y-auto">
                                {personnel.filter(p => p.id !== currentUser.id).map(p => (
                                    <button key={p.id} onClick={() => setRecipientIds(prev => prev.includes(p.id) ? prev.filter(id => id !== p.id) : [...prev, p.id])} className={`px-2.5 py-1 rounded-full text-[10px] font-bold border transition-colors ${recipientIds.includes(p.id) ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-500 border-gray-200'}`}>{p.fullName}</button>
                                ))}
                            </div>
                        </div>
                        <div><input className="w-full py-2 text-sm font-black border-b border-gray-100 outline-none focus:border-indigo-500 transition-colors" placeholder={t.subject} value={subject} onChange={e => setSubject(e.target.value)} /></div>
                        <div><textarea className="w-full h-48 py-2 text-sm text-gray-700 outline-none resize-none" placeholder={t.writeHere} value={body} onChange={e => setBody(e.target.value)} /></div>
                        {attachments.length > 0 && (
                            <div className="flex flex-wrap gap-2 pt-2">{attachments.map((f, i) => (
                                <div key={i} className="flex items-center gap-2 bg-gray-50 px-2 py-1 rounded border border-gray-200 text-[10px] font-bold">
                                    <span className="truncate max-w-[100px]">{f.name}</span>
                                    {f.status === 'uploading' && <span className="text-indigo-600">{Math.round(f.progress || 0)}%</span>}
                                    <button onClick={() => setAttachments(prev => prev.filter((_, idx) => idx !== i))}>✕</button>
                                </div>
                            ))}</div>
                        )}
                    </div>
                    <div className="p-4 border-t border-gray-100 flex items-center justify-between bg-gray-50 shrink-0">
                        <button onClick={() => fileInputRef.current?.click()} className="text-gray-500 hover:text-indigo-600"><IconPaperclip className="w-5 h-5" /></button>
                        <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileSelect} multiple />
                        <div className="flex gap-2">
                            <button onClick={() => setIsComposeOpen(false)} className="px-4 py-2 text-xs font-bold text-gray-500 hover:bg-gray-100 rounded-xl transition-colors">{t.cancel}</button>
                            <button onClick={handleSendMessage} disabled={isSending || recipientIds.length === 0} className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-xs font-black shadow-lg shadow-indigo-200 hover:bg-indigo-700 disabled:opacity-50 flex items-center gap-2">
                                {isSending ? t.sending : <><IconSend className="w-4 h-4" /> {t.send}</>}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

