          uploadFileWithProgress(file, (progress) => setAttachments(prev => prev.map(f => f.name === file.name ? { ...f, progress } : f)), (url) => setAttachments(prev => prev.map(f => f.name === file.name ? { ...f, content: url, status: 'success', progress: 100 } : f)), (err) => setAttachments(prev => prev.map(f => f.name === file.name ? { ...f, status: 'error' } : f)));
      }
  };

  return (
    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm flex flex-col h-[600px] w-full max-w-full overflow-hidden animate-fade-in">
        {/* --- Toolbar --- */}
        <div className="p-3 border-b border-gray-100 bg-white flex flex-wrap items-center gap-3 shrink-0">
            <div className="flex bg-gray-100 p-1 rounded-xl">
                <button onClick={() => setActiveTab('inbox')} className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all ${activeTab === 'inbox' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>{t.inbox}</button>
                <button onClick={() => setActiveTab('sent')} className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all ${activeTab === 'sent' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>{t.sent}</button>
            </div>
            <div className="relative flex-grow min-w-[150px]">
                <input className="w-full pl-8 pr-4 py-2 bg-gray-50 border border-transparent rounded-xl text-xs outline-none focus:bg-white focus:border-indigo-200" placeholder={t.search} value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                <IconSearch className="w-3.5 h-3.5 text-gray-400 absolute left-2.5 top-2.5" />
            </div>
            <button onClick={() => setIsComposeOpen(true)} className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-bold hover:bg-indigo-700 flex items-center gap-2 shrink-0">
                <IconPlus className="w-4 h-4" /> {t.compose}
            </button>
        </div>

        {/* --- List --- */}
        <div className="flex-grow overflow-y-auto bg-gray-50/30 overflow-x-hidden w-full">
            {filteredMessages.length === 0 ? (
                <div className="py-20 text-center text-gray-400 text-xs">{activeTab === 'inbox' ? 'صندوق خالی' : 'ارسالی خالی'}</div>
            ) : (
                <div className="divide-y divide-gray-100 w-full">
                    {filteredMessages.map(msg => {
                        const isUnread = activeTab === 'inbox' && !msg.readBy.includes(currentUser.id);
                        // True Summary: 40 chars max, no newlines
                        const summary = msg.body.replace(/[\n\r\s]+/g, ' ').trim().substring(0, 40);

                        return (
                            <div key={msg.id} onClick={() => handleMessageClick(msg)} className={`flex items-center gap-3 p-3 cursor-pointer hover:bg-white transition-colors min-w-0 w-full overflow-hidden ${isUnread ? 'bg-indigo-50/40' : 'bg-transparent'}`}>
                                <div className={`w-9 h-9 rounded-full flex items-center justify-center text-white text-[10px] font-black shrink-0 ${activeTab === 'inbox' ? 'bg-indigo-500' : 'bg-gray-400'}`}>
                                    {activeTab === 'inbox' ? msg.senderName.charAt(0) : <IconSend className="w-3.5 h-3.5" />}
                                </div>
                                <div className="flex-grow min-w-0">
                                    <div className="flex justify-between items-center mb-0.5 gap-2">
                                        <h4 className={`text-xs truncate ${isUnread ? 'font-black text-gray-900' : 'font-bold text-gray-700'}`}>
                                            {activeTab === 'inbox' ? msg.senderName : msg.recipientNames[0] + (msg.recipientNames.length > 1 ? '...' : '')}
                                        </h4>
                                        <span className="text-[9px] text-gray-400 whitespace-nowrap dir-ltr">
                                            {new Date(msg.createdAt).toLocaleDateString(lang === 'fa' ? 'fa-IR' : 'en-US')}
                                        </span>
                                    </div>
                                    <div className="flex items-center justify-between gap-2 min-w-0">
                                        <p className="text-[11px] truncate text-gray-500 min-w-0 flex-grow">
                                            <span className={`font-bold ${isUnread ? 'text-indigo-700' : 'text-gray-700'}`}>{msg.subject}</span>
                                            <span className="mx-1 text-gray-300">|</span>
                                            <span className="opacity-60">{summary}...</span>
                                        </p>
                                        {msg.files && msg.files.length > 0 && <IconPaperclip className="w-3 h-3 text-gray-300 shrink-0" />}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>

        {/* --- View Modal --- */}
        {selectedMessage && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm" onClick={() => setSelectedMessage(null)}>
                <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl flex flex-col max-h-[80vh]" onClick={e => e.stopPropagation()}>
                    <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                        <div className="min-w-0">
                            <h3 className="font-black text-gray-900 text-sm truncate">{selectedMessage.subject}</h3>
                            <div className="text-[10px] text-gray-500 mt-0.5">
                                {activeTab === 'inbox' ? t.from : t.to} {activeTab === 'inbox' ? selectedMessage.senderName : selectedMessage.recipientNames.join(', ')}
                            </div>
                        </div>
                        <button onClick={() => setSelectedMessage(null)} className="p-2 text-gray-400 hover:text-gray-600">✕</button>
                    </div>
                    <div className="p-6 overflow-y-auto flex-grow text-sm text-gray-700 leading-relaxed whitespace-pre-wrap break-words">
                        {selectedMessage.body}
                        {selectedMessage.files && selectedMessage.files.length > 0 && (
                            <div className="mt-6 pt-4 border-t border-gray-100 grid grid-cols-2 gap-2">
                                {selectedMessage.files.map((f, i) => (
                                    <a key={i} href={f.content} target="_blank" rel="noreferrer" className="flex items-center gap-2 p-2 bg-gray-50 rounded-lg border border-gray-200 text-[10px] font-bold truncate">
                                        <IconFile className="w-3.5 h-3.5 text-indigo-500" /> {f.name}
                                    </a>
                                ))}
                            </div>
                        )}
                    </div>
                    <div className="p-3 bg-gray-50 border-t flex justify-end gap-2">
                        {isMaster && <button onClick={() => { if(confirm('Delete?')) { deleteMessageFromCloud(selectedMessage.id); setSelectedMessage(null); } }} className="text-red-500 text-xs px-3 py-1">حذف</button>}
                        <button onClick={() => { 
                            setRecipientIds([selectedMessage.senderId]); 
                            setSubject(`Re: ${selectedMessage.subject}`); 
                            setBody(`\n\n--- ${selectedMessage.senderName} ---\n> ${selectedMessage.body}`);
                            setSelectedMessage(null); setIsComposeOpen(true); 
                        }} className="bg-indigo-600 text-white px-4 py-1.5 rounded-lg text-xs font-bold">{t.reply}</button>
                    </div>
                </div>
            </div>
        )}

        {/* --- Compose Modal --- */}
        {isComposeOpen && (
            <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm">
                <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl flex flex-col max-h-[90vh]">
                    <div className="p-4 bg-indigo-600 text-white flex justify-between items-center shrink-0">
                        <h3 className="font-black text-xs">{t.compose}</h3>
                        <button onClick={() => setIsComposeOpen(false)}>✕</button>
                    </div>
                    <div className="p-4 flex-grow overflow-y-auto space-y-4">
                        <div className="flex flex-wrap gap-1 p-2 bg-gray-50 border border-gray-200 rounded-xl max-h-24 overflow-y-auto">
                            {personnel.filter(p => p.id !== currentUser.id).map(p => (
                                <button key={p.id} onClick={() => setRecipientIds(prev => prev.includes(p.id) ? prev.filter(id => id !== p.id) : [...prev, p.id])} className={`px-2 py-1 rounded-full text-[10px] font-bold border transition-colors ${recipientIds.includes(p.id) ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-500 border-gray-200'}`}>{p.fullName}</button>
                            ))}
                        </div>
                        <input className="w-full py-1 text-sm font-black border-b border-gray-100 outline-none focus:border-indigo-500" placeholder={t.subject} value={subject} onChange={e => setSubject(e.target.value)} />
                        <textarea className="w-full h-40 text-sm text-gray-700 outline-none resize-none" placeholder={t.writeHere} value={body} onChange={e => setBody(e.target.value)} />
                        {attachments.length > 0 && (
                            <div className="flex flex-wrap gap-2">{attachments.map((f, i) => (
                                <div key={i} className="flex items-center gap-1 bg-gray-50 px-2 py-1 rounded text-[9px] font-bold border border-gray-200">
                                    <span className="truncate max-w-[80px]">{f.name}</span>
                                    {f.status === 'uploading' && <span className="text-indigo-600">{Math.round(f.progress || 0)}%</span>}
                                    <button onClick={() => setAttachments(prev => prev.filter((_, idx) => idx !== i))}>✕</button>
                                </div>
                            ))}</div>
                        )}
                    </div>
                    <div className="p-4 border-t flex justify-between items-center bg-gray-50 shrink-0">
                        <button onClick={() => fileInputRef.current?.click()} className="text-gray-500"><IconPaperclip className="w-5 h-5" /></button>
                        <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileSelect} multiple />
                        <div className="flex gap-2">
                            <button onClick={() => setIsComposeOpen(false)} className="px-3 py-1.5 text-xs text-gray-500">{t.cancel}</button>
                            <button onClick={handleSendMessage} disabled={isSending || recipientIds.length === 0} className="bg-indigo-600 text-white px-5 py-1.5 rounded-lg text-xs font-black disabled:opacity-50">
                                {isSending ? '...' : t.send}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useRef, useMemo } from 'react';
import { InternalMessage, Personnel, AttachedFile } from '../types';
import { IconMail, IconSend, IconInbox, IconPaperclip, IconTrash, IconFile, IconReply, IconPlus, IconSearch, IconUsers } from './Icons';
import { sendInternalMessage, updateMessageInCloud, deleteMessageFromCloud, uploadFileWithProgress } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  messages: InternalMessage[];
  lang: Language;
}

export const InternalMessenger: React.FC<Props> = ({ currentUser, personnel, messages, lang }) => {
  const [activeTab, setActiveTab] = useState<'inbox' | 'sent'>('inbox');
  const [selectedMessage, setSelectedMessage] = useState<InternalMessage | null>(null);
  const [isComposeOpen, setIsComposeOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Compose State
  const [recipientIds, setRecipientIds] = useState<string[]>([]);
  const [subject, setSubject] = useState('');
  const [body, setBody] = useState('');
  const [attachments, setAttachments] = useState<AttachedFile[]>([]);
  const [isSending, setIsSending] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isMaster = currentUser.username === 'master';

  const t = {
      fa: {
          inbox: 'ورودی',
          sent: 'ارسالی',
          compose: 'پیام جدید',
          search: 'جستجو...',
          subject: 'موضوع',
          body: 'متن',
          recipients: 'گیرندگان',
          send: 'ارسال',
          reply: 'پاسخ',
          delete: 'حذف',
          files: 'پیوست‌ها',
          cancel: 'انصراف',
          writeHere: 'متن پیام...'
      },
      en: {
          inbox: 'Inbox',
          sent: 'Sent',
          compose: 'New',
          search: 'Search...',
          subject: 'Subject',
          body: 'Message',
          recipients: 'To',
          send: 'Send',
          reply: 'Reply',
          delete: 'Delete',
          files: 'Files',
          cancel: 'Cancel',
          writeHere: 'Message...'
      }
  }[lang];

  const filteredMessages = useMemo(() => {
      let list = activeTab === 'inbox' 
          ? messages.filter(m => m.recipientIds.includes(currentUser.id))
          : messages.filter(m => m.senderId === currentUser.id);

      list = [...list].sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

      if (searchTerm.trim()) {
          const term = searchTerm.toLowerCase();
          list = list.filter(m => 
              m.subject.toLowerCase().includes(term) || 
              m.body.toLowerCase().includes(term) ||
              m.senderName.toLowerCase().includes(term)
          );
      }
      return list;
  }, [messages, activeTab, currentUser.id, searchTerm]);

  const handleSendMessage = async () => {
      if (recipientIds.length === 0 || !subject.trim() || !body.trim()) return;
      setIsSending(true);
      try {
          const recipientNames = recipientIds.map(id => personnel.find(p => p.id === id)?.fullName || 'Unknown');
          const newMessage: InternalMessage = { 
              id: `msg-${Date.now()}`, 
              senderId: currentUser.id, 
              senderName: currentUser.fullName, 
              recipientIds, 
              recipientNames, 
              subject, 
              body, 
              files: attachments.filter(f => f.status === 'success'), 
              createdAt: new Date().toISOString(), 
              readBy: [] 
          };
          await sendInternalMessage(newMessage);
          setIsComposeOpen(false);
          setRecipientIds([]); setSubject(''); setBody(''); setAttachments([]);
          setActiveTab('sent');
      } catch (e) { alert('Error!'); } finally { setIsSending(false); }
  };

  const handleMessageClick = (msg: InternalMessage) => {
      setSelectedMessage(msg);
      if (activeTab === 'inbox' && !msg.readBy.includes(currentUser.id)) {
          updateMessageInCloud(msg.id, { readBy: [...msg.readBy, currentUser.id] });
      }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files?.[0]) {
          const file = e.target.files[0];
          const newFile: AttachedFile = { name: file.name, size: file.size, type: file.type, content: '', status: 'uploading', progress: 0 };
          setAttachments(prev => [...prev, newFile]);
          uploadFileWithProgress(file, (progress) => setAttachments(prev => prev.map(f => f.name === file.name ? { ...f, progress } : f)), (url) => setAttachments(prev => prev.map(f => f.name === file.name ? { ...f, content: url, status: 'success', progress: 100 } : f)), (err) => setAttachments(prev => prev.map(f => f.name === file.name ? { ...f, status: 'error' } : f)));
      }
  };

  return (
    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm flex flex-col h-[600px] w-full max-w-full overflow-hidden animate-fade-in relative">
        {/* --- Header --- */}
        <div className="p-3 border-b border-gray-100 bg-white flex items-center justify-between gap-2 shrink-0">
            <div className="flex bg-gray-100 p-1 rounded-xl shrink-0">
                <button onClick={() => setActiveTab('inbox')} className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all ${activeTab === 'inbox' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>{t.inbox}</button>
                <button onClick={() => setActiveTab('sent')} className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all ${activeTab === 'sent' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>{t.sent}</button>
            </div>

            <div className="relative flex-grow max-w-md min-w-0">
                <input className="w-full pl-8 pr-4 py-2 bg-gray-50 border border-transparent rounded-xl text-xs outline-none focus:bg-white focus:border-indigo-200 transition-all" placeholder={t.search} value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                <IconSearch className="w-3.5 h-3.5 text-gray-400 absolute left-2.5 top-2.5" />
            </div>

            <button onClick={() => setIsComposeOpen(true)} className="bg-indigo-600 text-white p-2 sm:px-4 sm:py-2 rounded-xl text-xs font-bold hover:bg-indigo-700 flex items-center gap-2 shrink-0 shadow-lg shadow-indigo-100">
                <IconPlus className="w-4 h-4" /> <span className="hidden sm:inline">{t.compose}</span>
            </button>
        </div>

        {/* --- List Area --- */}
        <div className="flex-grow overflow-y-auto overflow-x-hidden bg-gray-50/30 w-full">
            {filteredMessages.length === 0 ? (
                <div className="py-20 text-center text-gray-400 text-xs">{activeTab === 'inbox' ? 'صندوق خالی' : 'ارسالی خالی'}</div>
            ) : (
                <div className="divide-y divide-gray-100">
                    {filteredMessages.map(msg => {
                        const isUnread = activeTab === 'inbox' && !msg.readBy.includes(currentUser.id);
                        // Summary logic: single line, no whitespace bloat
                        const bodySummary = msg.body.replace(/\s+/g, ' ').trim();

                        return (
                            <div 
                                key={msg.id} 
                                onClick={() => handleMessageClick(msg)} 
                                className={`flex items-center gap-3 p-3 cursor-pointer hover:bg-white transition-all w-full min-w-0 overflow-hidden relative ${isUnread ? 'bg-indigo-50/50' : 'bg-transparent'}`}
                            >
                                {isUnread && <div className="absolute right-0 top-0 w-1 h-full bg-indigo-600 shadow-[0_0_10px_rgba(79,70,229,0.5)]"></div>}

                                <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white text-[10px] font-black shrink-0 shadow-sm ${activeTab === 'inbox' ? 'bg-gradient-to-br from-indigo-400 to-indigo-600' : 'bg-gray-400'}`}>
                                    {activeTab === 'inbox' ? msg.senderName.charAt(0) : <IconSend className="w-4 h-4" />}
                                </div>

                                <div className="flex-grow min-w-0">
                                    <div className="flex justify-between items-center mb-0.5 gap-2">
                                        <h4 className={`text-xs truncate ${isUnread ? 'font-black text-gray-900' : 'font-bold text-gray-700'}`}>
                                            {activeTab === 'inbox' ? msg.senderName : msg.recipientNames[0] + (msg.recipientNames.length > 1 ? '...' : '')}
                                        </h4>
                                        <span className="text-[9px] text-gray-400 whitespace-nowrap dir-ltr">
                                            {new Date(msg.createdAt).toLocaleDateString(lang === 'fa' ? 'fa-IR' : 'en-US')}
                                        </span>
                                    </div>
                                    <div className="flex items-center gap-2 min-w-0">
                                        <div className={`text-[11px] flex-grow min-w-0 truncate ${isUnread ? 'text-indigo-900' : 'text-gray-500'}`}>
                                            <span className="font-black">{msg.subject}</span>
                                            <span className="mx-1 text-gray-300">|</span>
                                            <span className="opacity-70">{bodySummary}</span>
                                        </div>
                                        {msg.files && msg.files.length > 0 && <IconPaperclip className="w-3.5 h-3.5 text-gray-300 shrink-0" />}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>

        {/* --- View Modal (Full Message) --- */}
        {selectedMessage && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm" onClick={() => setSelectedMessage(null)}>
                <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl flex flex-col max-h-[85vh] animate-scale-in" onClick={e => e.stopPropagation()}>
                    <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50 shrink-0">
                        <div className="min-w-0">
                            <h3 className="font-black text-gray-900 text-sm truncate">{selectedMessage.subject}</h3>
                            <div className="text-[10px] text-gray-500 mt-0.5 flex gap-2">
                                <span>{activeTab === 'inbox' ? t.from : t.to} {activeTab === 'inbox' ? selectedMessage.senderName : selectedMessage.recipientNames.join(', ')}</span>
                                <span className="dir-ltr">{new Date(selectedMessage.createdAt).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</span>
                            </div>
                        </div>
                        <button onClick={() => setSelectedMessage(null)} className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors">✕</button>
                    </div>
                    <div className="p-6 overflow-y-auto flex-grow text-sm text-gray-700 leading-relaxed whitespace-pre-wrap break-words">
                        {selectedMessage.body}
                        {selectedMessage.files && selectedMessage.files.length > 0 && (
                            <div className="mt-8 pt-4 border-t border-gray-100 grid grid-cols-2 gap-2">
                                {selectedMessage.files.map((f, i) => (
                                    <a key={i} href={f.content} target="_blank" rel="noreferrer" className="flex items-center gap-2 p-2 bg-gray-50 rounded-xl border border-gray-200 hover:bg-indigo-50 hover:border-indigo-200 transition-all truncate">
                                        <IconFile className="w-4 h-4 text-indigo-500 shrink-0" />
                                        <span className="text-[10px] font-bold truncate">{f.name}</span>
                                    </a>
                                ))}
                            </div>
                        )}
                    </div>
                    <div className="p-3 bg-gray-50 border-t border-gray-100 flex justify-end gap-2 shrink-0">
                        {isMaster && <button onClick={() => { if(confirm('حذف؟')) { deleteMessageFromCloud(selectedMessage.id); setSelectedMessage(null); } }} className="ml-auto text-red-500 text-xs font-bold px-3 py-1.5 hover:bg-red-50 rounded-lg"><IconTrash className="w-4 h-4" /></button>}
                        <button onClick={() => { 
                            setRecipientIds([selectedMessage.senderId]); 
                            setSubject(`${lang==='fa'?'پاسخ:':'Re:'} ${selectedMessage.subject}`); 
                            setBody(`\n\n--- ${selectedMessage.senderName} ---\n> ${selectedMessage.body}`);
                            setSelectedMessage(null); 
                            setIsComposeOpen(true); 
                        }} className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-xs font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-200 transition-all">{t.reply}</button>
                    </div>
                </div>
            </div>
        )}

        {/* --- Compose Modal --- */}
        {isComposeOpen && (
            <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm" onClick={() => setIsComposeOpen(false)}>
                <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl flex flex-col max-h-[90vh] overflow-hidden" onClick={e => e.stopPropagation()}>
                    <div className="p-4 bg-indigo-600 text-white flex justify-between items-center shrink-0">
                        <h3 className="font-black text-sm flex items-center gap-2"><IconPlus className="w-4 h-4" /> {t.compose}</h3>
                        <button onClick={() => setIsComposeOpen(false)} className="hover:opacity-70">✕</button>
                    </div>
                    <div className="p-5 flex-grow overflow-y-auto space-y-5">
                        <div>
                            <label className="text-[10px] font-black text-gray-400 mb-1.5 block">{t.recipients}</label>
                            <div className="flex flex-wrap gap-1.5 p-2 bg-gray-50 border border-gray-200 rounded-xl max-h-24 overflow-y-auto">
                                {personnel.filter(p => p.id !== currentUser.id).map(p => (
                                    <button key={p.id} onClick={() => setRecipientIds(prev => prev.includes(p.id) ? prev.filter(id => id !== p.id) : [...prev, p.id])} className={`px-3 py-1 rounded-full text-[10px] font-bold border transition-all ${recipientIds.includes(p.id) ? 'bg-indigo-600 text-white border-indigo-600 shadow-sm' : 'bg-white text-gray-500 border-gray-200'}`}>{p.fullName}</button>
                                ))}
                            </div>
                        </div>
                        <div><input className="w-full py-2 text-sm font-black border-b border-gray-100 outline-none focus:border-indigo-500 transition-colors bg-transparent" placeholder={t.subject} value={subject} onChange={e => setSubject(e.target.value)} /></div>
                        <div><textarea className="w-full h-40 py-2 text-sm text-gray-700 outline-none resize-none bg-transparent" placeholder={t.writeHere} value={body} onChange={e => setBody(e.target.value)} /></div>
                        {attachments.length > 0 && (
                            <div className="flex flex-wrap gap-2 pt-2">{attachments.map((f, i) => (
                                <div key={i} className="flex items-center gap-2 bg-gray-50 px-2 py-1.5 rounded-lg border border-gray-200 text-[10px] font-bold">
                                    <span className="truncate max-w-[100px]">{f.name}</span>
                                    {f.status === 'uploading' && <span className="text-indigo-600 font-black">{Math.round(f.progress || 0)}%</span>}
                                    <button onClick={() => setAttachments(prev => prev.filter((_, idx) => idx !== i))} className="text-red-500">✕</button>
                                </div>
                            ))}</div>
                        )}
                    </div>
                    <div className="p-4 border-t border-gray-100 flex items-center justify-between bg-gray-50 shrink-0">
                        <button onClick={() => fileInputRef.current?.click()} className="text-gray-500 hover:text-indigo-600 transition-colors p-2 rounded-lg hover:bg-indigo-50"><IconPaperclip className="w-5 h-5" /></button>
                        <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileSelect} multiple />
                        <div className="flex gap-2">
                            <button onClick={() => setIsComposeOpen(false)} className="px-4 py-2 text-xs font-bold text-gray-500 hover:bg-gray-200 rounded-xl transition-colors">{t.cancel}</button>
                            <button onClick={handleSendMessage} disabled={isSending || recipientIds.length === 0} className="bg-indigo-600 text-white px-8 py-2 rounded-xl text-xs font-black shadow-lg shadow-indigo-200 hover:bg-indigo-700 disabled:opacity-50 transition-all flex items-center gap-2">
                                {isSending ? '...' : t.send}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

