  const filteredTickets = useMemo(() => {
    return [...tickets].filter(t => {
      // Step 1: Filter by Active/Archive status
      const isArchived = t.status === TicketStatus.COMPLETED || t.status === TicketStatus.CANCELLED;
      if (cartableMode === 'active' && isArchived) return false;
      if (cartableMode === 'archive' && !isArchived) return false;

      // Step 2: Filter by Mine/All
      const effectiveFilterMode = canViewAllTickets ? filterMode : 'my';
      if (effectiveFilterMode === 'my') {
         if (!(t.assignedTo === currentUser.id || t.projectData?.teamMemberIds?.includes(currentUser.id))) return false;
      }

      // Step 3: Status and Search
      if (statusFilter !== 'all' && t.status !== statusFilter) return false;
      if (globalSearch.trim()) {
          const term = globalSearch.toLowerCase();
          return (
              (t.id || '').toLowerCase().includes(term) ||
              (t.customerName || '').toLowerCase().includes(term) ||
              (t.companyName || '').toLowerCase().includes(term) || 
              (t.phoneNumber || '').includes(term)
