                          <span className="text-[10px] font-black text-gray-400">تغییر وضعیت:</span>
                          {Object.values(TicketStatus).map(s => (
                              <button key={s} onClick={() => handleUpdateTicketStatus(s)} className={`px-3 py-1 rounded-full text-[9px] font-black border transition-all ${tickets.find(t=>t.id===selectedTicketId)?.status === s ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-500 border-gray-200 hover:border-indigo-300'}`}>{s}</button>
                          ))}
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                          <div className="space-y-4">
                              <h4 className="font-black text-xs text-indigo-600 border-b pb-1">اطلاعات مشتری</h4>
                              <p className="text-sm font-bold text-gray-800">{tickets.find(t=>t.id===selectedTicketId)?.customerName}</p>
                              <p className="text-xs text-gray-500">{tickets.find(t=>t.id===selectedTicketId)?.description}</p>
                          </div>
                          <div className="space-y-4">
                              <h4 className="font-black text-xs text-indigo-600 border-b pb-1">تاریخچه تغییرات</h4>
                              <div className="space-y-3">
                                  {tickets.find(t=>t.id===selectedTicketId)?.timeline.map((entry, i) => (
                                      <div key={i} className="flex gap-2 text-[10px]">
                                          <span className="text-gray-400 font-mono shrink-0">{new Date(entry.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
                                          <span className="font-bold text-gray-700">{entry.title}:</span>
                                          <span className="text-gray-500">{entry.description}</span>
                                      </div>
                                  ))}
                              </div>
                          </div>
                      </div>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useMemo } from 'react';
import { InternalMessage, Personnel, AttachedFile } from '../types';
import { IconMail, IconSend, IconInbox, IconPaperclip, IconTrash, IconFile, IconReply, IconPlus, IconSearch } from './Icons';
import { sendInternalMessage, updateMessageInCloud, deleteMessageFromCloud, uploadFileWithProgress } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  messages: InternalMessage[];
  lang: Language;
}

export const InternalMessenger: React.FC<Props> = ({ currentUser, personnel, messages, lang }) => {
  const [activeTab, setActiveTab] = useState<'inbox' | 'sent'>('inbox');
  const [selectedMessage, setSelectedMessage] = useState<InternalMessage | null>(null);
  const [isComposeOpen, setIsComposeOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [recipientIds, setRecipientIds] = useState<string[]>([]);
  const [subject, setSubject] = useState('');
  const [body, setBody] = useState('');
  const [attachments, setAttachments] = useState<AttachedFile[]>([]);
  const [isSending, setIsSending] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const t = {
      fa: { inbox: 'ورودی', sent: 'ارسالی', compose: 'پیام جدید', search: 'جستجو...', recipients: 'گیرندگان', subject: 'موضوع', send: 'ارسال', reply: 'پاسخ', close: 'بستن' },
      en: { inbox: 'Inbox', sent: 'Sent', compose: 'New', search: 'Search...', recipients: 'To', subject: 'Subject', send: 'Send', reply: 'Reply', close: 'Close' }
  }[lang];

  const filteredMessages = useMemo(() => {
      let list = activeTab === 'inbox' 
          ? messages.filter(m => m.recipientIds.includes(currentUser.id))
          : messages.filter(m => m.senderId === currentUser.id);

      list = [...list].sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

      if (searchTerm.trim()) {
          const term = searchTerm.toLowerCase();
          list = list.filter(m => 
              m.subject.toLowerCase().includes(term) || 
              m.senderName.toLowerCase().includes(term)
          );
      }
      return list;
  }, [messages, activeTab, currentUser.id, searchTerm]);

  const handleMessageClick = (msg: InternalMessage) => {
      setSelectedMessage(msg);
      if (activeTab === 'inbox' && !msg.readBy.includes(currentUser.id)) {
          updateMessageInCloud(msg.id, { readBy: [...msg.readBy, currentUser.id] });
      }
  };

  const handleSendMessage = async () => {
    if (recipientIds.length === 0 || !subject.trim() || !body.trim()) return;
    setIsSending(true);
    try {
        const recipientNames = recipientIds.map(id => personnel.find(p => p.id === id)?.fullName || 'Unknown');
        const newMessage: InternalMessage = { 
            id: `msg-${Date.now()}`, senderId: currentUser.id, senderName: currentUser.fullName, recipientIds, recipientNames, subject, body, files: attachments.filter(f => f.status === 'success'), createdAt: new Date().toISOString(), readBy: [] 
        };
        await sendInternalMessage(newMessage);
        setIsComposeOpen(false);
        setRecipientIds([]); setSubject(''); setBody(''); setAttachments([]);
        setActiveTab('sent');
    } catch (e) { alert('خطا'); } finally { setIsSending(false); }
  };

  return (
    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm flex flex-col h-[600px] w-full max-w-full overflow-hidden animate-fade-in relative">
        {/* Toolbar */}
        <div className="p-3 border-b border-gray-100 flex items-center justify-between gap-2 shrink-0">
            <div className="flex bg-gray-100 p-1 rounded-xl">
                <button onClick={() => setActiveTab('inbox')} className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all ${activeTab === 'inbox' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>{t.inbox}</button>
                <button onClick={() => setActiveTab('sent')} className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all ${activeTab === 'sent' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>{t.sent}</button>
            </div>
            <div className="relative flex-grow max-w-xs">
                <input className="w-full pl-8 pr-3 py-2 bg-gray-50 rounded-xl text-[10px] outline-none border-transparent focus:border-indigo-200" placeholder={t.search} value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                <IconSearch className="w-3.5 h-3.5 text-gray-400 absolute left-2.5 top-2.5" />
            </div>
            <button onClick={() => setIsComposeOpen(true)} className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-bold hover:bg-indigo-700 flex items-center gap-2 shrink-0">
                <IconPlus className="w-4 h-4" /> {t.compose}
            </button>
        </div>

        {/* Message List */}
        <div className="flex-grow overflow-y-auto overflow-x-hidden bg-gray-50/20 w-full">
            {filteredMessages.length === 0 ? (
                <div className="py-20 text-center text-gray-400 text-xs font-bold">بدون پیام</div>
            ) : (
                <div className="divide-y divide-gray-100">
                    {filteredMessages.map(msg => {
                        const isUnread = activeTab === 'inbox' && !msg.readBy.includes(currentUser.id);
                        const bodyPreview = msg.body.replace(/\s+/g, ' ').trim();
                        return (
                            <div key={msg.id} onClick={() => handleMessageClick(msg)} className={`flex items-center gap-3 p-3 cursor-pointer hover:bg-white transition-all min-w-0 overflow-hidden relative ${isUnread ? 'bg-indigo-50/50' : 'bg-transparent'}`}>
                                {isUnread && <div className="absolute right-0 top-0 w-1 h-full bg-indigo-600 shadow-sm"></div>}
                                <div className={`w-9 h-9 rounded-full flex items-center justify-center text-white text-[10px] font-black shrink-0 ${activeTab === 'inbox' ? 'bg-indigo-500' : 'bg-gray-400'}`}>
                                    {activeTab === 'inbox' ? msg.senderName.charAt(0) : <IconSend className="w-3.5 h-3.5" />}
                                </div>
                                <div className="flex-grow min-w-0">
                                    <div className="flex justify-between items-center mb-0.5">
                                        <h4 className={`text-[11px] truncate ${isUnread ? 'font-black text-gray-900' : 'font-bold text-gray-700'}`}>
                                            {activeTab === 'inbox' ? msg.senderName : msg.recipientNames[0] + (msg.recipientNames.length > 1 ? '...' : '')}
                                        </h4>
                                        <span className="text-[9px] text-gray-400 dir-ltr">{new Date(msg.createdAt).toLocaleDateString(lang === 'fa' ? 'fa-IR' : 'en-US')}</span>
                                    </div>
                                    <p className="text-[10px] text-gray-500 line-clamp-1 truncate w-full">
                                        <span className={`font-bold ${isUnread ? 'text-indigo-800' : 'text-gray-700'}`}>{msg.subject}</span>
                                        <span className="mx-1 text-gray-300">|</span>
                                        <span className="opacity-60">{bodyPreview}</span>
                                    </p>
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>

        {/* View Modal */}
        {selectedMessage && (
            <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm" onClick={() => setSelectedMessage(null)}>
                <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl flex flex-col max-h-[80vh] overflow-hidden" onClick={e => e.stopPropagation()}>
                    <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50 shrink-0">
                        <div className="min-w-0">
                            <h3 className="font-black text-gray-900 text-sm truncate">{selectedMessage.subject}</h3>
                            <div className="text-[10px] text-gray-500 mt-0.5">از: {selectedMessage.senderName}</div>
                        </div>
                        <button onClick={() => setSelectedMessage(null)} className="p-2 text-gray-400 hover:text-red-500 transition-colors font-bold">✕</button>
                    </div>
                    <div className="p-6 overflow-y-auto flex-grow text-sm text-gray-700 leading-relaxed whitespace-pre-wrap break-words">
                        {selectedMessage.body}
                        {selectedMessage.files && selectedMessage.files.length > 0 && (
                            <div className="mt-6 pt-4 border-t border-gray-100 grid grid-cols-2 gap-2">
                                {selectedMessage.files.map((f, i) => (
                                    <a key={i} href={f.content} target="_blank" rel="noreferrer" className="flex items-center gap-2 p-2 bg-gray-50 rounded-lg border border-gray-200 text-[10px] font-bold truncate">
                                        <IconFile className="w-3.5 h-3.5 text-indigo-500" /> {f.name}
                                    </a>
                                ))}
                            </div>
                        )}
                    </div>
                    <div className="p-3 bg-gray-50 border-t flex justify-end gap-2 shrink-0">
                        <button onClick={() => { 
                            setRecipientIds([selectedMessage.senderId]); 
                            setSubject(`${lang==='fa'?'پاسخ:':'Re:'} ${selectedMessage.subject}`); 
                            setBody(`\n\n--- ${selectedMessage.senderName} ---\n> ${selectedMessage.body}`);
                            setSelectedMessage(null); setIsComposeOpen(true); 
                        }} className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-xs font-black shadow-lg hover:bg-indigo-700">{t.reply}</button>
                    </div>
                </div>
            </div>
        )}

        {/* Compose Modal */}
        {isComposeOpen && (
            <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm" onClick={() => setIsComposeOpen(false)}>
                <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl flex flex-col max-h-[90vh] overflow-hidden" onClick={e => e.stopPropagation()}>
                    <div className="p-4 bg-indigo-600 text-white flex justify-between items-center shrink-0">
                        <h3 className="font-black text-xs">{t.compose}</h3>
                        <button onClick={() => setIsComposeOpen(false)}>✕</button>
                    </div>
                    <div className="p-5 flex-grow overflow-y-auto space-y-4">
                        <div className="flex flex-wrap gap-1 p-2 bg-gray-50 border border-gray-200 rounded-xl max-h-24 overflow-y-auto">
                            {personnel.filter(p => p.id !== currentUser.id).map(p => (
                                <button key={p.id} onClick={() => setRecipientIds(prev => prev.includes(p.id) ? prev.filter(id => id !== p.id) : [...prev, p.id])} className={`px-2.5 py-1 rounded-full text-[10px] font-bold border transition-colors ${recipientIds.includes(p.id) ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-500 border-gray-200'}`}>{p.fullName}</button>
                            ))}
                        </div>
                        <input className="w-full py-2 text-sm font-black border-b border-gray-100 outline-none focus:border-indigo-500" placeholder={t.subject} value={subject} onChange={e => setSubject(e.target.value)} />
                        <textarea className="w-full h-40 py-2 text-sm text-gray-700 outline-none resize-none" placeholder="متن پیام..." value={body} onChange={e => setBody(e.target.value)} />
                    </div>
                    <div className="p-4 border-t border-gray-100 flex justify-end gap-3 bg-gray-50 shrink-0">
                        <button onClick={() => setIsComposeOpen(false)} className="px-4 py-2 text-xs font-bold text-gray-500">{lang==='fa'?'انصراف':'Cancel'}</button>
                        <button onClick={handleSendMessage} disabled={isSending || recipientIds.length === 0} className="bg-indigo-600 text-white px-8 py-2 rounded-xl text-xs font-black shadow-lg hover:bg-indigo-700 disabled:opacity-50">
                            {isSending ? '...' : t.send}
                        </button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Ticket, TicketStatus, ServiceOption, Personnel, Customer, AppConfig, ProjectDetails, AttachedFile, Currency, Payment, InternalMessage, Invoice, Task, Meeting, SystemLog, ProjectMilestone, ProjectRisk, ProjectTeamMember, KPI, CustomForm, PerformanceReport } from '../types';
import { IconCheck, IconActivity, IconUsers, IconBriefcase, IconLayout, IconPaperclip, IconShield, IconSettings, IconClock, IconFile, IconEdit, IconTrash, IconProject, IconMoney, IconUpload, IconPlus, IconChart, IconMail, IconInvoice, IconList, IconCalendarClock, IconHistory, IconCopy, IconSearch, IconFlag, IconAlertTriangle, IconTime, IconTrendingUp, IconRefreshCw, IconLock, IconMegaphone, IconBarChart2, IconMapPin, IconWhatsapp, IconTarget, IconClipboard, IconFolder, IconAward } from './Icons';
import { ServiceManager } from './ServiceManager';
import { PersonnelManager } from './PersonnelManager';
import { CustomerManager } from './CustomerManager';
import { SettingsManager } from './SettingsManager';
import { InternalMessenger } from './InternalMessenger';
import { InvoiceModal } from './InvoiceModal';
import { TaskManager } from './TaskManager';
import { MeetingCalendar } from './MeetingCalendar';
import { PerformanceReports } from './PerformanceReports';
import { KPIManager } from './KPIManager';
import { SalesDashboard } from './SalesDashboard';
import { ReportManager } from './ReportManager';
import { uploadFileWithProgress, logSystemAction, subscribeToSystemLogs, saveTaskToCloud, restoreEntityFromLog, sendInternalMessage, subscribeToCustomForms, saveReport } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  tickets: Ticket[];
  services: ServiceOption[];
  personnel: Personnel[];
  customers: Customer[];
  messages: InternalMessage[];
  tasks: Task[]; 
  meetings: Meeting[]; 
  kpis?: KPI[];
  config: AppConfig;
  onCreateTicket: (ticket: Ticket) => Promise<void>;
  onUpdateTicket: (ticketId: string, updates: Partial<Ticket>, actorName: string, actionNote?: string, visibility?: 'public' | 'internal') => void;
  onDeleteTicket: (ticketId: string) => Promise<void>;
  onUpdateServices: (services: ServiceOption[]) => void;
  onUpdatePersonnel: (personnel: Personnel[]) => void;
  onUpdateCustomers: (customers: Customer[]) => void; 
  onEditCustomer: (id: string, updates: Partial<Customer>) => Promise<void>;
  onDeleteCustomer: (id: string) => Promise<void>;
  onUpdateConfig: (config: AppConfig) => void;
  onLogout: () => void;
  lang: Language;
}

export const AdminDashboard: React.FC<Props> = ({ 
  currentUser, tickets, services, personnel, customers, messages, tasks, meetings, kpis = [], config, onCreateTicket, onUpdateTicket, onDeleteTicket, onUpdateServices, onUpdatePersonnel, onUpdateCustomers, onEditCustomer, onDeleteCustomer, onUpdateConfig, onLogout, lang
}) => {
  const isAdmin = currentUser?.roles.includes('مدیر');
  const isMaster = currentUser?.username === 'master';

  const canAssign = isAdmin || isMaster || currentUser?.permissions?.canAssign;
  const hasCustomerAccess = isAdmin || isMaster || currentUser?.permissions?.canViewCustomers;
  const hasTariffAccess = isAdmin || isMaster || currentUser?.permissions?.canViewTariffs;
  const canViewAllTickets = isAdmin || isMaster || currentUser?.permissions?.canViewAllTickets;

  const [activeTab, setActiveTab] = useState<'overview' | 'projects' | 'services' | 'personnel' | 'customers' | 'settings' | 'financial' | 'messages' | 'tasks' | 'meetings' | 'logs' | 'reports' | 'kpi' | 'forms' | 'sales' | 'staff_reports'>('overview');
  const [cartableMode, setCartableMode] = useState<'active' | 'archive'>('active');
  const [filterMode, setFilterMode] = useState<'all' | 'my'>(canViewAllTickets ? 'all' : 'my');
  const [statusFilter, setStatusFilter] = useState<TicketStatus | 'all'>('all');
  const [globalSearch, setGlobalSearch] = useState(''); 
  const [currentPage, setCurrentPage] = useState(1);
  const ITEMS_PER_PAGE = 10;

  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);

  const t = {
      fa: {
          overview: 'کارتابل اصلی',
          activeItems: 'درخواست‌های فعال',
          archiveItems: 'تاریخچه / بایگانی',
          row: 'ردیف',
          code: 'کد / متقاضی',
          service: 'سرویس',
          status: 'وضعیت',
          action: 'مشاهده',
          tasks: 'امور روزانه',
          messages: 'مکاتبات',
          projects: 'پروژه‌ها',
          customers: 'مشتریان',
          services: 'تعرفه‌ها',
          personnel: 'پرسنل',
          settings: 'تنظیمات',
          logout: 'خروج',
          searchPlaceholder: 'جستجو در کارتابل...',
          notFound: 'موردی یافت نشد.',
          prev: 'قبلی',
          next: 'بعدی'
      },
      en: {
          overview: 'Main Cartable',
          activeItems: 'Active Requests',
          archiveItems: 'History / Archive',
          row: 'No.',
          code: 'ID / Applicant',
          service: 'Service',
          status: 'Status',
          action: 'View',
          tasks: 'Tasks',
          messages: 'Mail',
          projects: 'Projects',
          customers: 'Customers',
          services: 'Tariffs',
          personnel: 'Staff',
          settings: 'Settings',
          logout: 'Logout',
          searchPlaceholder: 'Search...',
          notFound: 'No items found.',
          prev: 'Prev',
          next: 'Next'
      }
  }[lang];

  const filteredTickets = useMemo(() => {
    return [...tickets].filter(t => {
      // Logic for Archiving
      const isCompletedOrCancelled = t.status === TicketStatus.COMPLETED || t.status === TicketStatus.CANCELLED;
      if (cartableMode === 'active' && isCompletedOrCancelled) return false;
      if (cartableMode === 'archive' && !isCompletedOrCancelled) return false;

      const effectiveFilterMode = canViewAllTickets ? filterMode : 'my';
      if (effectiveFilterMode === 'my') {
         if (!(t.assignedTo === currentUser.id || t.projectData?.teamMemberIds?.includes(currentUser.id))) return false;
      }
      if (statusFilter !== 'all' && t.status !== statusFilter) return false;
      if (globalSearch.trim()) {
          const term = globalSearch.toLowerCase();
          return (t.id || '').toLowerCase().includes(term) || (t.customerName || '').toLowerCase().includes(term) || (t.companyName || '').toLowerCase().includes(term);
      }
      return true;
    }).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [tickets, cartableMode, filterMode, statusFilter, globalSearch, currentUser.id, canViewAllTickets]);

  const totalPages = Math.ceil(filteredTickets.length / ITEMS_PER_PAGE);
  const paginatedTickets = filteredTickets.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

  const getServiceTitle = (id: string) => {
      const s = services.find(s => s.id === id);
      return s ? (lang === 'en' && s.titleEn ? s.titleEn : s.title) : id;
  };

  const getStatusBadge = (status: TicketStatus) => {
    switch(status) {
      case TicketStatus.SUBMITTED: return 'bg-blue-50 text-blue-700 border-blue-100';
      case TicketStatus.PROCESSING: return 'bg-purple-50 text-purple-700 border-purple-100';
      case TicketStatus.IN_PROGRESS: return 'bg-amber-50 text-amber-700 border-amber-100';
      case TicketStatus.COMPLETED: return 'bg-emerald-50 text-emerald-700 border-emerald-100';
      case TicketStatus.CANCELLED: return 'bg-gray-100 text-gray-500 border-gray-200';
      default: return 'bg-gray-50 text-gray-700';
    }
  };

  const handleUpdateTicketStatus = (status: TicketStatus) => {
    if (!selectedTicketId) return;
    onUpdateTicket(selectedTicketId, { status }, currentUser.fullName);
  };

  return (
    <div className="flex flex-col md:flex-row gap-6 min-h-[calc(100vh-100px)] w-full max-w-full overflow-hidden">
      {/* Sidebar */}
      <div className="w-full md:w-64 shrink-0">
         <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm flex flex-col items-center sticky top-24">
            <div className="w-20 h-20 rounded-full overflow-hidden border-2 border-indigo-100 shadow-sm mb-3">
                {currentUser.avatar ? <img src={currentUser.avatar} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-indigo-50 flex items-center justify-center text-indigo-600 text-2xl font-black">{currentUser.fullName.charAt(0)}</div>}
            </div>
            <h3 className="font-bold text-gray-900 text-sm mb-4">{currentUser.fullName}</h3>

            <div className="w-full space-y-1">
                {[
                    { id: 'overview', icon: <IconActivity />, label: t.overview },
                    { id: 'tasks', icon: <IconList />, label: t.tasks },
                    { id: 'messages', icon: <IconMail />, label: t.messages },
                    { id: 'projects', icon: <IconProject />, label: t.projects },
                    { id: 'customers', icon: <IconUsers />, label: t.customers, hidden: !hasCustomerAccess },
                    { id: 'services', icon: <IconBriefcase />, label: t.services, hidden: !hasTariffAccess },
                    { id: 'personnel', icon: <IconShield />, label: t.personnel, hidden: !isAdmin },
                    { id: 'settings', icon: <IconSettings />, label: t.settings, hidden: !isAdmin }
                ].filter(m => !m.hidden).map(m => (
                    <button key={m.id} onClick={() => setActiveTab(m.id as any)} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl text-xs font-bold transition-all ${activeTab === m.id ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-50'}`}>
                        <span className="w-4 h-4">{m.icon}</span> {m.label}
                    </button>
                ))}
            </div>
            <button onClick={onLogout} className="w-full text-xs font-black text-red-500 bg-red-50 hover:bg-red-100 py-2.5 rounded-xl transition-colors mt-6">{t.logout}</button>
         </div>
      </div>

      {/* Main Content */}
      <div className="flex-grow min-w-0 max-w-full">
        {activeTab === 'overview' && (
            <div className="space-y-6 animate-fade-in w-full">
                 <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden flex flex-col w-full">
                     <div className="p-4 border-b border-gray-100 flex flex-col sm:flex-row justify-between items-center gap-4 bg-gray-50/50">
                         {/* Cartable Tabs */}
                         <div className="flex bg-gray-200 p-1 rounded-xl shrink-0">
                             <button onClick={() => { setCartableMode('active'); setCurrentPage(1); }} className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all ${cartableMode === 'active' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>{t.activeItems}</button>
                             <button onClick={() => { setCartableMode('archive'); setCurrentPage(1); }} className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all ${cartableMode === 'archive' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>{t.archiveItems}</button>
                         </div>

                         <div className="flex flex-wrap gap-2 w-full sm:w-auto justify-end min-w-0">
                             {canViewAllTickets && (
                                 <select className="bg-white border border-gray-200 text-[10px] font-black px-3 py-1.5 rounded-lg outline-none" value={filterMode} onChange={(e) => setFilterMode(e.target.value as any)}>
                                     <option value="my">میز کار من</option>
                                     <option value="all">کل شرکت</option>
                                 </select>
                             )}
                             <div className="relative flex-grow sm:flex-none">
                                <input type="text" className="w-full sm:w-48 pl-8 pr-3 py-1.5 bg-white border border-gray-200 rounded-lg text-[10px] outline-none" placeholder={t.searchPlaceholder} value={globalSearch} onChange={e => setGlobalSearch(e.target.value)} />
                                <IconSearch className="w-3 h-3 text-gray-400 absolute left-2.5 top-2.5" />
                             </div>
                         </div>
                     </div>

                     <div className="overflow-x-auto w-full">
                         <table className="w-full text-start table-fixed min-w-[600px]">
                             <thead className="bg-gray-50 text-gray-400 text-[10px] font-black uppercase tracking-wider">
                                 <tr>
                                     <th className="px-4 py-3 w-12 text-center border-b border-gray-100">{t.row}</th>
                                     <th className="px-4 py-3 text-start w-1/3 border-b border-gray-100">{t.code}</th>
                                     <th className="px-4 py-3 text-start border-b border-gray-100">{t.service}</th>
                                     <th className="px-4 py-3 text-start w-28 border-b border-gray-100">{t.status}</th>
                                     <th className="px-4 py-3 w-16 text-center border-b border-gray-100">{t.action}</th>
                                 </tr>
                             </thead>
                             <tbody className="divide-y divide-gray-50">
                                 {paginatedTickets.map((ticket, index) => (
                                     <tr key={ticket.id} className="hover:bg-indigo-50/30 transition-colors group">
                                         <td className="px-4 py-4 text-center text-[10px] font-black text-gray-300">
                                             {(currentPage - 1) * ITEMS_PER_PAGE + index + 1}
                                         </td>
                                         <td className="px-4 py-4 min-w-0">
                                             <div className="flex flex-col truncate">
                                                 <span className="text-[9px] font-mono text-indigo-400 mb-0.5">{ticket.id}</span>
                                                 <span className="font-bold text-gray-800 text-xs truncate">{ticket.customerName}</span>
                                                 {ticket.companyName && <span className="text-[9px] text-gray-400 truncate">{ticket.companyName}</span>}
                                             </div>
                                         </td>
                                         <td className="px-4 py-4">
                                             <div className="text-xs font-medium text-gray-600 truncate">{getServiceTitle(ticket.serviceId)}</div>
                                             <div className="text-[9px] text-gray-400 mt-0.5">{new Date(ticket.createdAt).toLocaleDateString(lang === 'fa' ? 'fa-IR' : 'en-US')}</div>
                                         </td>
                                         <td className="px-4 py-4">
                                             <span className={`px-2 py-1 rounded text-[9px] font-black border ${getStatusBadge(ticket.status)}`}>{ticket.status}</span>
                                         </td>
                                         <td className="px-4 py-4 text-center">
                                             <button onClick={() => setSelectedTicketId(ticket.id)} className="bg-white border border-gray-200 text-gray-600 p-1.5 rounded-lg hover:bg-indigo-600 hover:text-white transition-all shadow-sm">
                                                 <IconSearch className="w-3.5 h-3.5" />
                                             </button>
                                         </td>
                                     </tr>
                                 ))}
                             </tbody>
                         </table>
                         {paginatedTickets.length === 0 && <div className="text-center py-20 text-gray-400 text-xs font-bold">{t.notFound}</div>}
                     </div>

                     {totalPages > 1 && (
                        <div className="flex justify-between items-center p-4 border-t border-gray-100 bg-gray-50/30">
                            <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="px-3 py-1.5 bg-white border border-gray-200 rounded-lg text-[10px] font-black disabled:opacity-50">{t.prev}</button>
                            <span className="text-[10px] font-bold text-gray-500">{currentPage} / {totalPages}</span>
                            <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="px-3 py-1.5 bg-white border border-gray-200 rounded-lg text-[10px] font-black disabled:opacity-50">{t.next}</button>
                        </div>
                     )}
                 </div>
            </div>
        )}

        {/* Tab content placeholder for others to keep file standard */}
        {activeTab === 'messages' && <InternalMessenger currentUser={currentUser} personnel={personnel} messages={messages} lang={lang} />}
        {activeTab === 'tasks' && <TaskManager currentUser={currentUser} personnel={personnel} tasks={tasks} lang={lang} />}
        {activeTab === 'customers' && <CustomerManager customers={customers} currentUser={currentUser} onUpdate={onUpdateCustomers} onEdit={onEditCustomer} onDelete={onDeleteCustomer} lang={lang} />}
        {activeTab === 'services' && <ServiceManager services={services} onUpdate={onUpdateServices} readonly={!isAdmin && !isMaster} lang={lang} />}
        {activeTab === 'personnel' && <PersonnelManager personnel={personnel} config={config} onUpdate={onUpdatePersonnel} onUpdateConfig={onUpdateConfig} lang={lang} />}
        {activeTab === 'settings' && <SettingsManager config={config} onUpdate={onUpdateConfig} isMaster={isMaster} />}
        {activeTab === 'sales' && <SalesDashboard currentUser={currentUser} personnel={personnel} services={services} onUpdatePersonnel={onUpdatePersonnel} onUpdateServices={onUpdateServices} lang={lang} />}
        {activeTab === 'staff_reports' && <ReportManager currentUser={currentUser} personnel={personnel} lang={lang} config={config} />}
      </div>

      {/* Detail Modal */}
      {selectedTicketId && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm" onClick={() => setSelectedTicketId(null)}>
              <div className="bg-white w-full max-w-2xl rounded-2xl shadow-2xl flex flex-col max-h-[90vh] overflow-hidden" onClick={e => e.stopPropagation()}>
                  <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-indigo-600 text-white shrink-0">
                      <h3 className="font-black text-sm">جزئیات پرونده #{selectedTicketId}</h3>
                      <button onClick={() => setSelectedTicketId(null)} className="hover:opacity-70">✕</button>
                  </div>
                  <div className="p-6 overflow-y-auto flex-grow space-y-6">
                      <div className="flex flex-wrap items-center gap-3 bg-gray-50 p-4 rounded-xl border border-gray-200">
                          <span className="text-[10px] font-black text-gray-400">تغییر وضعیت به:</span>
                          {Object.values(TicketStatus).map(s => (
                              <button key={s} onClick={() => handleUpdateTicketStatus(s)} className={`px-3 py-1 rounded-full text-[9px] font-black border transition-all ${tickets.find(t=>t.id===selectedTicketId)?.status === s ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-500 border-gray-200'}`}>{s}</button>
                          ))}
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div className="space-y-4">
                              <h4 className="font-black text-xs text-indigo-600 border-b pb-1">اطلاعات مشتری</h4>
                              <p className="text-sm font-bold text-gray-800">{tickets.find(t=>t.id===selectedTicketId)?.customerName}</p>
                              <p className="text-xs text-gray-500">{tickets.find(t=>t.id===selectedTicketId)?.description}</p>
                          </div>
                      </div>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useMemo } from 'react';
import { InternalMessage, Personnel, AttachedFile } from '../types';
import { IconMail, IconSend, IconInbox, IconPaperclip, IconTrash, IconFile, IconReply, IconPlus, IconSearch } from './Icons';
import { sendInternalMessage, updateMessageInCloud, deleteMessageFromCloud, uploadFileWithProgress } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  messages: InternalMessage[];
  lang: Language;
}

export const InternalMessenger: React.FC<Props> = ({ currentUser, personnel, messages, lang }) => {
  const [activeTab, setActiveTab] = useState<'inbox' | 'sent'>('inbox');
  const [selectedMessage, setSelectedMessage] = useState<InternalMessage | null>(null);
  const [isComposeOpen, setIsComposeOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [recipientIds, setRecipientIds] = useState<string[]>([]);
  const [subject, setSubject] = useState('');
  const [body, setBody] = useState('');
  const [attachments, setAttachments] = useState<AttachedFile[]>([]);
  const [isSending, setIsSending] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const t = {
      fa: { inbox: 'ورودی', sent: 'ارسالی', compose: 'پیام جدید', search: 'جستجو...', recipients: 'گیرندگان', subject: 'موضوع', send: 'ارسال', reply: 'پاسخ', close: 'بستن' },
      en: { inbox: 'Inbox', sent: 'Sent', compose: 'New', search: 'Search...', recipients: 'To', subject: 'Subject', send: 'Send', reply: 'Reply', close: 'Close' }
  }[lang];

  const filteredMessages = useMemo(() => {
      let list = activeTab === 'inbox' 
          ? messages.filter(m => m.recipientIds.includes(currentUser.id))
          : messages.filter(m => m.senderId === currentUser.id);

      list = [...list].sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

      if (searchTerm.trim()) {
          const term = searchTerm.toLowerCase();
          list = list.filter(m => 
              m.subject.toLowerCase().includes(term) || 
              m.senderName.toLowerCase().includes(term)
          );
      }
      return list;
  }, [messages, activeTab, currentUser.id, searchTerm]);

  const handleMessageClick = (msg: InternalMessage) => {
      setSelectedMessage(msg);
      if (activeTab === 'inbox' && !msg.readBy.includes(currentUser.id)) {
          updateMessageInCloud(msg.id, { readBy: [...msg.readBy, currentUser.id] });
      }
  };

  const handleSendMessage = async () => {
    if (recipientIds.length === 0 || !subject.trim() || !body.trim()) return;
    setIsSending(true);
    try {
        const recipientNames = recipientIds.map(id => personnel.find(p => p.id === id)?.fullName || 'Unknown');
        const newMessage: InternalMessage = { 
            id: `msg-${Date.now()}`, senderId: currentUser.id, senderName: currentUser.fullName, recipientIds, recipientNames, subject, body, files: attachments.filter(f => f.status === 'success'), createdAt: new Date().toISOString(), readBy: [] 
        };
        await sendInternalMessage(newMessage);
        setIsComposeOpen(false);
        setRecipientIds([]); setSubject(''); setBody(''); setAttachments([]);
        setActiveTab('sent');
    } catch (e) { alert('خطا'); } finally { setIsSending(false); }
  };

  return (
    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm flex flex-col h-[600px] w-full max-w-full overflow-hidden animate-fade-in relative">
        {/* Toolbar */}
        <div className="p-3 border-b border-gray-100 flex items-center justify-between gap-2 shrink-0 bg-white">
            <div className="flex bg-gray-100 p-1 rounded-xl shrink-0">
                <button onClick={() => setActiveTab('inbox')} className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all ${activeTab === 'inbox' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>{t.inbox}</button>
                <button onClick={() => setActiveTab('sent')} className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all ${activeTab === 'sent' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>{t.sent}</button>
            </div>
            <div className="relative flex-grow max-w-xs min-w-0">
                <input className="w-full pl-8 pr-3 py-2 bg-gray-50 rounded-xl text-[10px] outline-none border border-transparent focus:border-indigo-200" placeholder={t.search} value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                <IconSearch className="w-3.5 h-3.5 text-gray-400 absolute left-2.5 top-2.5" />
            </div>
            <button onClick={() => setIsComposeOpen(true)} className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-bold hover:bg-indigo-700 flex items-center gap-2 shrink-0">
                <IconPlus className="w-4 h-4" /> <span className="hidden sm:inline">{t.compose}</span>
            </button>
        </div>

        {/* Message List */}
        <div className="flex-grow overflow-y-auto overflow-x-hidden bg-gray-50/20 w-full">
            {filteredMessages.length === 0 ? (
                <div className="py-20 text-center text-gray-400 text-xs font-bold">بدون پیام</div>
            ) : (
                <div className="divide-y divide-gray-100">
                    {filteredMessages.map(msg => {
                        const isUnread = activeTab === 'inbox' && !msg.readBy.includes(currentUser.id);
                        const bodyPreview = msg.body.replace(/\s+/g, ' ').trim();
                        return (
                            <div key={msg.id} onClick={() => handleMessageClick(msg)} className={`flex items-center gap-3 p-3 cursor-pointer hover:bg-white transition-all w-full min-w-0 overflow-hidden relative ${isUnread ? 'bg-indigo-50/50' : 'bg-transparent'}`}>
                                {isUnread && <div className="absolute right-0 top-0 w-1 h-full bg-indigo-600 shadow-sm"></div>}
                                <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white text-[10px] font-black shrink-0 ${activeTab === 'inbox' ? 'bg-gradient-to-br from-indigo-400 to-indigo-600' : 'bg-gray-400'}`}>
                                    {activeTab === 'inbox' ? msg.senderName.charAt(0) : <IconSend className="w-4 h-4" />}
                                </div>
                                <div className="flex-grow min-w-0">
                                    <div className="flex justify-between items-center mb-0.5 gap-2">
                                        <h4 className={`text-[11px] truncate ${isUnread ? 'font-black text-gray-900' : 'font-bold text-gray-700'}`}>
                                            {activeTab === 'inbox' ? msg.senderName : msg.recipientNames[0] + (msg.recipientNames.length > 1 ? '...' : '')}
                                        </h4>
                                        <span className="text-[9px] text-gray-400 whitespace-nowrap dir-ltr">{new Date(msg.createdAt).toLocaleDateString(lang === 'fa' ? 'fa-IR' : 'en-US')}</span>
                                    </div>
                                    <p className="text-[10px] text-gray-500 truncate w-full min-w-0">
                                        <span className={`font-bold ${isUnread ? 'text-indigo-800' : 'text-gray-700'}`}>{msg.subject}</span>
                                        <span className="mx-1 text-gray-300">|</span>
                                        <span className="opacity-60">{bodyPreview}</span>
                                    </p>
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>

        {/* View Modal */}
        {selectedMessage && (
            <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm" onClick={() => setSelectedMessage(null)}>
                <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl flex flex-col max-h-[80vh] overflow-hidden" onClick={e => e.stopPropagation()}>
                    <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50 shrink-0">
                        <div className="min-w-0">
                            <h3 className="font-black text-gray-900 text-sm truncate">{selectedMessage.subject}</h3>
                            <div className="text-[10px] text-gray-500 mt-0.5">از: {selectedMessage.senderName}</div>
                        </div>
                        <button onClick={() => setSelectedMessage(null)} className="p-2 text-gray-400 hover:text-red-500 transition-colors font-bold">✕</button>
                    </div>
                    <div className="p-6 overflow-y-auto flex-grow text-sm text-gray-700 leading-relaxed whitespace-pre-wrap break-words">
                        {selectedMessage.body}
                        {selectedMessage.files && selectedMessage.files.length > 0 && (
                            <div className="mt-6 pt-4 border-t border-gray-100 grid grid-cols-2 gap-2">
                                {selectedMessage.files.map((f, i) => (
                                    <a key={i} href={f.content} target="_blank" rel="noreferrer" className="flex items-center gap-2 p-2 bg-gray-50 rounded-lg border border-gray-200 text-[10px] font-bold truncate">
                                        <IconFile className="w-3.5 h-3.5 text-indigo-500" /> {f.name}
                                    </a>
                                ))}
                            </div>
                        )}
                    </div>
                    <div className="p-3 bg-gray-50 border-t flex justify-end gap-2 shrink-0">
                        <button onClick={() => { 
                            setRecipientIds([selectedMessage.senderId]); 
                            setSubject(`${lang==='fa'?'پاسخ:':'Re:'} ${selectedMessage.subject}`); 
                            setBody(`\n\n--- ${selectedMessage.senderName} ---\n> ${selectedMessage.body}`);
                            setSelectedMessage(null); setIsComposeOpen(true); 
                        }} className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-xs font-black shadow-lg hover:bg-indigo-700">{t.reply}</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};
